// Ladin Ormanı — 4. sınıf Sosyal Bilgiler: test tarzı (kullanıcının örnek aldığı yayın). İki sütun, haftada 8 soru,
// 2 sayfa + ayrı cevap anahtarı sayfası. Soru kalıpları 3 haftalık döngüyle döner (aynı kalıp art arda iki haftada gelmez):
//   1., 4., 7. … hafta: kodDY, yolDY, kapDY, konusma · 2., 5., 8. …: roma, sirala, esle, bulmaca · 3., 6., 9. …: kacTane, kareYol, tabloSec, cocukSec
//   her hafta ayrıca belge/grafik/metin soruları + 1 ortak bağlamlı ikili grup. Motor: test4.js. Üretim: node kaynak/calisma-kagitlari/uret.js s4
module.exports = ({ T }) => {
  const { p, madde, tablo, bilgi, kodDY, yolDY, kapDY, konusma, roma, sirala, esle, bulmaca, kacTane, kareYol, tabloSec, cocukSec, grafikSec, ortak, coktan, grafik, sayfa, optik, yeniHafta, cevapSayfasi } = T;
  const kimlik = o => `<div class="b4-kimlik"><div class="b4-k-ust">TÜRKİYE CUMHURİYETİ KİMLİK KARTI</div><div class="b4-k-ic"><div class="b4-k-foto">👤</div><dl>${o.map(([a, b]) => `<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl></div></div>`;
  const serit = l => `<div class="b4-serit">${l.map(([a, b]) => `<div><b>${a}</b><span>${b}</span></div>`).join('')}</div>`;
  const etiket = o => `<div class="b4-etiket">${o.map(([a, b]) => `<div><span>${a}</span><b>${b}</b></div>`).join('')}</div>`;
  const W = (hafta, unite, baslik, konu, f) => ({ unite, hafta, baslik, konu, sayfalar: () => { yeniHafta(); const [a, b] = f(); return [sayfa(a), sayfa(b).replace(/<\/div>$/, optik() + '</div>'), cevapSayfasi(`${hafta}. hafta · ${baslik}`)]; } });
  void madde; void bilgi; void grafikSec; void etiket;

  const S4 = {
    'hafta-01': W(1, 1, 'Kimliğimi Tanıyorum', 'Resmî kimlik belgesi', () => [[
      kodDY('Öğretmen tahtaya kimlik kartıyla ilgili bilgiler yazdı. Öğrencilerden bilgi doğruysa "Doğru", yanlışsa "Yanlış" bölümünü boyamalarını istedi.', [
        ['Kimlik kartında kişinin doğum tarihi yazar.', true], ['T.C. kimlik numarası kardeşlerde aynıdır.', false], ['Kimlik kartının bir son geçerlilik tarihi vardır.', true], ['Kimlik kartından kişinin boyu öğrenilir.', false]], 'a1'),
      coktan(p('Defne, 2026 yılının eylül ayında kimlik kartını inceliyor.') + kimlik([['Soyadı', 'YILMAZ'], ['Adı', 'DEFNE'], ['Doğum Tarihi', '14.03.2017'], ['Cinsiyeti', 'K'], ['Uyruğu', 'T.C.'], ['Son Geçerlilik', '14.03.2027']]),
        'Buna göre Defne\'nin kimlik kartıyla ilgili aşağıdakilerden hangisi söylenebilir?', 'Defne bu tarihte 9 yaşındadır.', ['Kartın geçerlilik süresi dolmuştur.', 'Defne\'nin doğum günü sonbahardadır.', 'Kart 2028 yılına kadar kullanılabilir.']),
      konusma('Dört arkadaş kimlik kartlarıyla ilgili bildiklerini paylaşıyor.', [
        ['Ali', 'Kimlik numaramız bize özeldir, başka kimsede yoktur.', true], ['Ece', 'Kimlik kartının arka yüzünde anne ve baba adı bulunur.', true],
        ['Can', 'Kimlik kartının süresi dolsa da hep kullanılabilir.', false], ['Su', 'Kimlik kartında okulumuzun adı yazar.', false]], 'a3'),
      yolDY('Mert, kişisel bilgilerin korunmasıyla ilgili bir oyun oynuyor. İfade doğruysa "D", yanlışsa "Y" okunu izliyor.', [
        ['Tanımadığımız kişilerle ev adresimizi paylaşmamalıyız.', true], ['İnternette kimlik numaramızı herkese yazabiliriz.', false], ['Şifremizi en yakın arkadaşımıza da söylemeliyiz.', false]], 'a4')], [
      ortak(p('Sınıf arkadaşları kimlik kartlarındaki doğum tarihlerini karşılaştırıyor.') + tablo(['Öğrenci', 'Doğum tarihi'], [['Defne', '14.03.2017'], ['Ayşe', '14.11.2016'], ['Kaan', '02.03.2017']]), [
        () => coktan('', 'Buna göre en büyük öğrenci kimdir?', 'Ayşe', ['Defne', 'Kaan', 'Üçü aynı yaştadır.']),
        () => coktan('', 'Kaan\'ın doğum gününden kaç gün sonra Defne\'nin doğum günü gelir?', '12', ['10', '11', '14'])]),
      kapDY('Bilge Öğretmen, öğrencilerin hazırladığı bilgi kartlarını inceliyor. Bilgi doğruysa "Doğru Bilgi", yanlışsa "Yanlış Bilgi" kabına atıyor.', [
        ['Kimlik kartı resmî bir belgedir.', true], ['Bebeklerin kimlik kartı olmaz.', false], ['Kimlik kartında uyruk bilgisi bulunur.', true], ['Kimlik kartı hiç yenilenmez.', false], ['Kişisel bilgilerimizi korumalıyız.', true]], 'a6'),
      coktan(p('Mert, bir oyun sitesine üye olurken site ondan aşağıdaki bilgileri istiyor.') + tablo(['İstenen bilgi'], [['Kullanıcı adı'], ['T.C. kimlik numarası'], ['Ev adresi'], ['Okulunun adı']]),
        'Buna göre Mert\'in ailesine danışmadan paylaşabileceği tek bilgi aşağıdakilerden hangisidir?', 'Gerçek adını içermeyen bir kullanıcı adı', ['T.C. kimlik numarası', 'Ev adresi', 'Okulunun adı ve sınıfı'])]]),

    'hafta-02': W(2, 1, 'Farklılıklarımız Zenginliğimiz', 'Farklı özelliklere saygı', () => [[
      coktan(p('4-A sınıfındaki her öğrenci en sevdiği tek etkinliği seçti.') + grafik('En sevilen etkinlikler', ['Spor', 'Resim', 'Müzik', 'Kitap', 'Bilim'], [8, 5, 4, 6, 3], 'Öğrenci'),
        'Grafiğe göre aşağıdakilerden hangisi söylenemez?', 'Müziği seçen öğrenci sayısı resmi seçenlerden fazladır.', ['Sınıfta 26 öğrenci vardır.', 'Spor ve kitabı seçenler, resim ve müziği seçenlerden fazladır.', 'En az seçilen etkinlik bilimdir.']),
      roma(p('Teneffüste takım kuran Deniz, "Selin yavaş koşuyor, onu almayalım." dedi. Selin "Koşmakta iyi değilim ama kaleci olabilirim." diye cevap verdi. Can da "Herkesin iyi olduğu bir şey vardır, Selin kaleci olsun." dedi.'),
        'Bu olayla ilgili aşağıdaki yargılardan hangileri doğrudur?', [['Deniz, arkadaşının farklı özelliklerine saygı göstermemiştir.', true], ['Selin, güçlü olduğu yanı fark etmiştir.', true], ['Can, takımın yalnız hızlı oyunculardan oluşmasını istemiştir.', false]]),
      sirala('4-B sınıfı, herkesin katılacağı bir "Etkinlik Günü" planlıyor. Planın adımları karışık verilmiştir.', [
        'Herkesin etkinlik önerisini almak', 'Önerileri oylamak', 'Görevleri yeteneklere göre paylaştırmak', 'Etkinlik gününü gerçekleştirmek', 'Etkinliği birlikte değerlendirmek'], 'Bu planın adımları doğru sırayla hangi seçenekte verilmiştir?', 'b3'),
      bulmaca('Sınıf panosuna "Birlikte yaşamanın değerleri" bulmacası asıldı.', [['Başkalarının düşüncelerine değer vermek.', 'SAYGI'], ['Kendini başkasının yerine koymak.', 'EMPATİ'], ['İyiliği unutmamak.', 'VEFA'], ['Birine inanıp dayanmak.', 'GÜVEN'], ['Köyde birlikte iş yapma geleneği.', 'İMECE']], 'b4')], [
      esle('"Farklılıklar Şenliği" için öğrencilere ilgi alanlarına uygun görevler verilecek.', [
        ['Piyano çalmayı seven Ayşe', 'Müzik dinletisi'], ['Resim yapmayı seven Can', 'Pano tasarımı'], ['Yemek yapmayı seven Elif', 'Yöresel tatlar köşesi'], ['Konuşmayı seven Bora', 'Sunuculuk']],
        'Buna göre öğrencilerle görevlerin doğru eşleştirilmesi hangisidir?', 'b5'),
      ortak(p('Okulumuzda "Farklılıklar Şenliği" yapıldı. Öğrenciler ailelerinin geldiği şehirlerin yemeklerini, türkülerini ve oyunlarını tanıttı. Görme engelli öğrencimiz Ayşe de piyanoda bir eser çaldı. Şenliğin sonunda herkes en çok neyi sevdiğini bir panoya yazdı.'), [
        () => coktan('', 'Bu şenlikle ilgili aşağıdakilerden hangisi söylenemez?', 'Öğrenciler yalnızca kendi şehirlerinin kültürünü tanımıştır.', ['Farklı kültürler bir arada tanıtılmıştır.', 'Engelli bir öğrenci de etkinliğe katkı sunmuştur.', 'Öğrencilerin görüşlerine yer verilmiştir.']),
        () => coktan('', 'Şenliğin düzenlenme amacı en çok hangisi olabilir?', 'Farklılıkların bir zenginlik olduğunu fark ettirmek', ['Öğrencileri yarıştırıp birinciyi seçmek', 'Ders saatlerini azaltmak', 'Yalnızca yemek tanıtmak'])]),
      coktan(p('Sınıfa başka bir ülkeden gelen Lina katıldı. Lina Türkçeyi yeni öğreniyor ve teneffüste genellikle yalnız oturuyor.'), 'Lina\'nın sınıfa uyum sağlaması için yapılabilecek en uygun davranış hangisidir?', 'Ona oyunlarımızı öğretip kendi ülkesinin oyunlarını sormak', ['Türkçeyi öğrenene kadar onunla konuşmamak', 'Onu yalnızca öğretmene bırakmak', 'Farklı konuştuğu için ona gülmek'])]]),

    'hafta-03': W(3, 1, 'Yaşam Çizgim', 'Önemli olayları kronolojik sıralama', () => [[
      kacTane(p('Elif yaşamındaki önemli olayları bir zaman şeridinde gösterdi.') + serit([['2016', 'Doğdu'], ['2018', 'Yürüdü'], ['2020', 'Kardeşi doğdu'], ['2022', 'Okula başladı'], ['2024', 'Bisiklet sürdü'], ['2026', '4. sınıf']]) + p('Öğretmen, zaman şeridine bakan öğrencilerin yorumlarını tahtaya yazdı:'), [
        ['Elif okula başladığında 6 yaşındaydı.', true], ['Elif\'in kardeşi Elif\'ten 4 yaş küçüktür.', true], ['Elif bisiklet sürmeyi kardeşi doğmadan önce öğrenmiştir.', false], ['Olaylar eskiden yeniye doğru sıralanmıştır.', true]]),
      tabloSec(p('Elif, zaman şeridindeki olayları belgelerle kanıtlamak istiyor. Elinde aile fotoğraf albümü, 1. sınıf karnesi ve bisiklet yarışı katılım belgesi var.'), 'Elif\'in olayları kanıtlamak için kullanabileceği belgeler hangi seçenekte doğru verilmiştir?',
        ['Yürümesi', 'Okula başlaması', 'Bisiklet sürmesi'], ['Fotoğraf albümü', 'Karne', 'Katılım belgesi'], [['Karne', 'Fotoğraf albümü', 'Katılım belgesi'], ['Fotoğraf albümü', 'Katılım belgesi', 'Karne'], ['Katılım belgesi', 'Karne', 'Fotoğraf albümü']], 'c2'),
      kareYol('Kaan, zaman ve kronoloji bilgileriyle bir oyun oynuyor.', [['Kronoloji, olayları oluş sırasına göre dizmektir.', true], ['Zaman şeridinde en yeni olay en başa yazılır.', false], ['Aile büyüklerinin anlattıkları geçmişi öğrenmede kaynak olabilir.', true], ['Karne, doğduğumuz yılı kanıtlayan belgedir.', false]], 'c3'),
      coktan(p('Kerem 2016, kardeşi Zehra 2019, kuzeni Ali 2014 yılında doğmuştur. Üçü de 2026 yılında doğum günlerini kutlamıştır.'), 'Buna göre aşağıdakilerden hangisi doğrudur?', 'Ali, Zehra\'dan 5 yaş büyüktür.', ['Kerem en küçük çocuktur.', 'Zehra 2026\'da 8 yaşındadır.', 'Ali ile Kerem aynı yaştadır.'])], [
      cocukSec(p('Elif annesiyle yaptığı söyleşide şunları öğrendi: "İlk sözcüğünü 1 yaşında söyledin. 3 yaşında anaokuluna başladın. 5 yaşında ilk kitabını okudun."') + p('Elif\'in arkadaşları bu bilgiler hakkında konuşuyor.'), 'Buna göre hangi çocuğun söylediği yanlıştır?',
        ['Elif kitap okumayı anaokuluna başlamadan önce öğrenmiştir.', 'Bu olayların en eskisi ilk sözcüğüdür.', 'Elif anaokuluna 3 yaşında başlamıştır.', 'Elif bu bilgileri sözlü tarih yoluyla öğrenmiştir.'], 'c5'),
      ortak(p('Ali, dedesinin hayatını bir zaman şeridinde gösterdi.') + serit([['1950', 'Dedem doğdu'], ['1957', 'Okula başladı'], ['1975', 'Evlendi'], ['1978', 'Babam doğdu'], ['2016', 'Ben doğdum']]), [
        () => coktan('', 'Ali doğduğunda dedesi kaç yaşındaydı?', '66', ['56', '62', '68']),
        () => coktan('', 'Zaman şeridine göre aşağıdakilerden hangisi söylenemez?', 'Dedesi evlendiğinde Ali\'nin babası 3 yaşındaydı.', ['Dedesi okula 7 yaşında başlamıştır.', 'Babası doğduğunda dedesi 28 yaşındaydı.', 'Ali, babasından 38 yaş küçüktür.'])]),
      coktan(p('Zeynep geçmişini öğrenmek için farklı kaynaklar topluyor.'), 'Aşağıdakilerden hangisi Zeynep\'in kendi geçmişini öğrenmek için kullanabileceği bir kaynak değildir?', 'Bir gazetenin hava durumu sayfası', ['Bebeklik fotoğrafları', 'Aşı kartı', 'Annesinin anıları'])]]),

    'hafta-04': W(4, 1, 'Ailemde Rollerim', 'Aile içi roller ve sorumluluklar', () => [[
      ortak(p('Zeynep\'in ailesi evdeki görevleri aşağıdaki çizelgeyle paylaştı.') + tablo(['Görev', 'Anne', 'Baba', 'Zeynep (10)', 'Emre (6)'], [['Yemek yapmak', '✓', '✓', '', ''], ['Sofrayı kurmak', '', '', '✓', '✓'], ['Çöpü atmak', '', '✓', '✓', ''], ['Bitkileri sulamak', '', '', '', '✓'], ['Alışveriş', '✓', '✓', '', '']]), [
        () => coktan('', 'Çizelgeye göre hangi görevi tek bir kişi yapmaktadır?', 'Bitkileri sulamak', ['Yemek yapmak', 'Sofrayı kurmak', 'Alışveriş']),
        () => coktan('', 'Zeynep bir hafta okul gezisine gidecektir. Zeynep yokken görevleri çizelgedeki öteki kişiler sürdürecektir. Buna göre bu hafta hangisi doğru olur?', 'Sofrayı Emre, çöpü baba tek başına yapar.', ['Yemeği yalnız Emre yapar.', 'Alışverişi Emre yapar.', 'Bitkileri anne sular.'])]),
      kodDY('Öğretmen aile içi roller ve sorumluluklarla ilgili ifadeler hazırladı. Öğrenciler doğru bilgilerin "Doğru", yanlış bilgilerin "Yanlış" bölümünü boyayacak.', [
        ['Ailede her bireyin yaşına uygun sorumlulukları vardır.', true], ['Ev işleri yalnızca annelerin görevidir.', false], ['Bir kişi görevini yapmazsa ailenin düzeni etkilenebilir.', true], ['Çocuklar aile kararlarında hiç fikir belirtemez.', false]], 'd2'),
      yolDY('Emre, ailedeki roller hakkında bir yol oyunu oynuyor.', [['Bir kişi ailede hem çocuk hem kardeş rolüne sahip olabilir.', true], ['Ailedeki roller hiçbir zaman değişmez.', false], ['Görev paylaşımı işleri kolaylaştırır.', true]], 'd3')], [
      konusma('Kerem, ailesinin hafta sonu planını herkesin fikrini alarak yaptığını anlattı. Arkadaşları da yorum yaptı.', [
        ['Ada', 'Kararı herkesin fikrini alarak vermek doğru bir davranıştır.', true], ['Bora', 'Ailede kararları yalnız en büyük kişi vermelidir.', false],
        ['Ece', 'Çocuklar da aile toplantısında görüşünü söyleyebilir.', true], ['Mert', 'Farklı fikirler olursa toplantı hemen bitirilmelidir.', false]], 'd4'),
      kapDY('Öğrenciler "evde sorumluluk" konusunda bilgi kartları hazırladı. Öğretmen kartları kaplara atıyor.', [
        ['Odamı toplamak benim sorumluluğumdur.', true], ['Kardeşime yardım etmek yalnız annemin işidir.', false], ['Sorumluluklarımızı zamanında yapmak güven oluşturur.', true], ['Evde görev almak çocuklar için gereksizdir.', false]], 'd5', 'doğru'),
      coktan(p('Zeynep sofrayı kurmayı unuttu çünkü oyun oynuyordu. Annesi işten yorgun geldi ve sofrayı kendisi kurdu. Yemek yarım saat geç yendi. Ertesi gün Zeynep görevini unutmamak için bir hatırlatma notu yazdı.'),
        'Bu olayla ilgili aşağıdakilerden hangisi söylenemez?', 'Zeynep\'in görevini yapmaması aileyi hiç etkilememiştir.', ['Bir kişinin görevini yapmaması ailenin düzenini aksatır.', 'Zeynep hatasından ders çıkarmıştır.', 'Zeynep\'in görevi annesine ek yük olmuştur.'])]]),

    'hafta-05': W(5, 1, 'Grupta Karar Alıyorum', 'Grup içinde sorumluluk ve ortak karar', () => [[
      ortak(p('4-A sınıfında 28 öğrenci var. Herkes gezi yeri için bir oy kullandı.') + tablo(['Gezi yeri', 'Oy sayısı'], [['Bilim merkezi', '12'], ['Hayvanat bahçesi', '9'], ['Müze', '?']]), [
        () => coktan('', 'Müzeye kaç oy verilmiştir?', '7', ['5', '6', '9']),
        () => coktan('', 'Müzeyi seçen öğrencilerin yapması gereken en doğru davranış hangisidir?', 'Çoğunluğun kararına saygı gösterip geziye katılmak', ['Oylamanın yeniden yapılmasında ısrar etmek', 'Geziye katılmamak', 'Kendi aralarında ayrı bir geziye gitmek'])]),
      roma(p('Proje grubunda Bora poster çizecek, Ela bilgileri yazacak, Arda sunumu yapacak. Sunum günü Arda hazırlıksız geldi. Bora ve Ela sunumu birlikte yaptılar, sonra grup toplanıp sorunun nedenini konuştu.'),
        'Bu durumla ilgili aşağıdaki yargılardan hangileri doğrudur?', [['Bir üyenin görevini yapmaması bütün grubu etkilemiştir.', true], ['Grup sorunu çözmek için iş birliği yapmıştır.', true], ['Grup çalışmasında görev dağılımı gereksizdir.', false]]),
      sirala('Sınıf temsilcisi Ece, sınıftaki bir sorunu çözmek için yapılacakları listeledi.', ['Sorunu herkesle birlikte belirlemek', 'Çözüm önerilerini toplamak', 'Önerileri oylamak', 'Seçilen çözümü uygulamak'], 'Ece\'nin adımları doğru sırayla hangisidir?', 'e3'),
      bulmaca('Grup çalışmasıyla ilgili bulmacayı çözen öğrenciler renkli kutulardaki harflerden bir sözcük buluyor.', [['Seçimde tercihimizi belirttiğimiz hak.', 'OY'], ['Bir kişinin grupta üstlendiği görev.', 'ROL'], ['Kararların konuşulduğu buluşma.', 'TOPLANTI'], ['Tartışmanın uzlaşmayla bitmesi.', 'ANLAŞMA'], ['Herkesin uyması gereken düzen.', 'KURAL']], 'e4')], [
      esle('Sınıf, okul bahçesini güzelleştirme projesinde görev dağılımı yapıyor.', [['Çizim yapmayı seven Can', 'Afiş hazırlamak'], ['Bitkilerden anlayan Ece', 'Fide dikmek'], ['Hesap yapmayı seven Kaan', 'Malzeme bütçesini çıkarmak'], ['İyi konuşan Ada', 'Müdüre projeyi sunmak']], 'Buna göre öğrencilerle görevlerin doğru eşleştirilmesi hangisidir?', 'e5'),
      coktan(p('4-A sınıfı ilk hafta herkesin önerisini alarak sınıf kurallarını belirledi ve sözleşmeyi herkes imzaladı. Bir ay sonra öğretmen, kurallara uyma oranının geçen yıla göre çok arttığını gördü.'),
        'Kurallara uyma oranının artmasının en önemli nedeni hangisi olabilir?', 'Kuralların herkesin katılımıyla belirlenmiş olması', ['Kuralların sayısının çok olması', 'Sınıfın daha kalabalık olması', 'Kuralların yalnızca öğretmen tarafından konması']),
      coktan(p('Bir grup çalışmasında Defne ile Kerem aynı konuda farklı fikirler savunuyor ve tartışma büyüyor.'), 'Bu anlaşmazlığı çözmek için yapılabilecek en uygun davranış hangisidir?', 'İki fikri de dinleyip ortak bir çözüm aramak', ['Sesi en yüksek olanın fikrini kabul etmek', 'Grubu dağıtmak', 'Tartışmayı kimseye söylemeden bırakmak'])]]),

    'hafta-06': W(6, 2, 'Aile Tarihim', 'Aile tarihi ve soy ağacı', () => [[
      kacTane(p('Kaan\'ın soy ağacındaki bilgiler aşağıda verilmiştir.') + tablo(['Kuşak', 'Babasının ailesi', 'Annesinin ailesi'], [['1. kuşak', 'Dede Ali, Nine Hatice', 'Dede Veli, Nine Zehra'], ['2. kuşak', 'Baba Murat', 'Anne Sevgi'], ['3. kuşak', 'Kaan ve kardeşi Ece', '']]) + p('Kaan\'ın arkadaşları soy ağacına bakarak şu yorumları yaptı:'), [
        ['Dede Veli, Kaan\'ın annesinin babasıdır.', true], ['Ece, Nine Hatice\'nin torunudur.', true], ['Murat, Zehra\'nın oğludur.', false], ['Soy ağacında üç kuşak gösterilmiştir.', true]]),
      kareYol('Defne, aile tarihi bilgileriyle kare oyunu oynuyor.', [['Soy ağacı aile bireylerini kuşaklar hâlinde gösterir.', true], ['Annemin annesi benim halamdır.', false], ['Aile büyükleriyle söyleşi yapmak aile tarihini öğrenme yoludur.', true], ['Eski fotoğraflar aile tarihi için kaynak olamaz.', false], ['Gelenekler kuşaktan kuşağa aktarılabilir.', true]], 'g2'),
      tabloSec(p('Kaan, aile tarihi araştırmasında kimden hangi bilgiyi alacağını planlıyor. Dedesi köyde öğretmenlik yapmış, ninesi düğün geleneklerini çok iyi biliyor, babası ise ailenin eski fotoğraflarını saklıyor.'), 'Kaan\'ın sorularını kime sorması en uygundur?',
        ['Eski okullar', 'Düğün gelenekleri', 'Eski fotoğraflar'], ['Dedesi', 'Ninesi', 'Babası'], [['Babası', 'Ninesi', 'Dedesi'], ['Ninesi', 'Dedesi', 'Babası'], ['Dedesi', 'Babası', 'Ninesi']], 'g3'),
      coktan(p('Kaan dedesiyle söyleşi yaptı. Dedesi: "Köyümüzde okul yoktu. Her sabah 5 kilometre yürüyerek komşu köydeki okula giderdik. Kışın karda yol açardık. Akşamları gaz lambasının ışığında ders çalışırdık." dedi.'),
        'Dedesinin anlattıklarına göre aşağıdakilerden hangisi geçmişle bugün arasındaki bir fark değildir?', 'Çocukların okula gitmesi', ['Okula ulaşmanın kolaylığı', 'Evlerin aydınlatılma biçimi', 'Okulların köylere uzaklığı'])], [
      cocukSec(p('Öğretmen "Aile tarihinizi nasıl öğrenebilirsiniz?" diye sordu. Dört öğrenci cevap verdi.'), 'Hangi öğrencinin önerdiği yol aile tarihini öğrenmek için uygun değildir?',
        ['Ünlü bir oyuncunun hayatını anlatan filmi izlemek', 'Dedemle ninemle söyleşi yapmak', 'Ailemizin eski fotoğraflarını incelemek', 'Evdeki eski belgelere bakmak'], 'g5'),
      ortak(p('Elif\'in ailesi her bayramda büyüklerini ziyaret ediyor. Bu gelenek Elif\'in büyük dedesinden beri sürüyor. Ziyaretlerde nine çocuklara eski bayramları anlatıyor; Elif de bu anıları bir deftere yazıyor.'), [
        () => coktan('', 'Bu gelenekle ilgili aşağıdakilerden hangisi söylenebilir?', 'Ailede dört kuşaktır sürmektedir.', ['Yalnızca Elif\'in başlattığı yeni bir alışkanlıktır.', 'Bayramlarda yapılmamaktadır.', 'Çocuklar bu gelenekte yer almaz.']),
        () => coktan('', 'Elif\'in anıları deftere yazmasının en önemli yararı nedir?', 'Aile tarihinin gelecek kuşaklara aktarılması', ['Ninesinin daha az konuşması', 'Bayramların kısalması', 'Ziyaretlerin azalması'])]),
      coktan(p('Ece\'nin soy ağacında annesinin kız kardeşi Leyla, babasının erkek kardeşi Can yer alıyor.'), 'Buna göre Leyla ve Can, Ece\'nin nesi olur?', 'Leyla teyzesi, Can amcası', ['Leyla halası, Can dayısı', 'Leyla teyzesi, Can dayısı', 'Leyla halası, Can amcası'])]]),

    'hafta-07': W(7, 2, 'Cumhuriyet Bayramı', 'Millî bayramlar ve kültürel ögeler', () => [[
      kodDY('Öğrenciler millî bayramlarla ilgili kartları değerlendiriyor.', [
        ['Cumhuriyet 29 Ekim 1923\'te ilan edilmiştir.', true], ['23 Nisan, Zafer Bayramı olarak kutlanır.', false], ['19 Mayıs 1919\'da Atatürk Samsun\'a çıkmıştır.', true], ['Millî bayramlarda bayrak asılmaz.', false]], 'h1'),
      ortak(p('Millî bayramlarımız aşağıdaki tabloda verilmiştir.') + tablo(['Bayram', 'Tarih', 'Kutladığımız olay'], [['Ulusal Egemenlik ve Çocuk Bayramı', '23 Nisan', 'TBMM\'nin açılışı (1920)'], ['Atatürk\'ü Anma, Gençlik ve Spor Bayramı', '19 Mayıs', 'Samsun\'a çıkış (1919)'], ['Zafer Bayramı', '30 Ağustos', 'Büyük Zafer (1922)'], ['Cumhuriyet Bayramı', '29 Ekim', 'Cumhuriyet\'in ilanı (1923)']]), [
        () => coktan('', 'Bu olaylar eskiden yeniye doğru sıralandığında üçüncü sırada hangisi yer alır?', 'Büyük Zafer', ['TBMM\'nin açılışı', 'Samsun\'a çıkış', 'Cumhuriyet\'in ilanı']),
        () => coktan('', '2026 yılında Cumhuriyet\'in kaçıncı yılı kutlanır?', '103.', ['100.', '101.', '106.'])]),
      konusma('Okul, 29 Ekim için hazırlık yapıyor. Öğrenciler bayramla ilgili düşüncelerini söylüyor.', [
        ['Ali', 'Cumhuriyetle birlikte yöneticileri millet seçmeye başladı.', true], ['Su', 'Cumhuriyet Bayramı yalnız Ankara\'da kutlanır.', false],
        ['Efe', 'Bayramda fener alayı yapmak bir gelenektir.', true], ['Ada', 'Cumhuriyet, Kurtuluş Savaşı\'ndan önce ilan edildi.', false]], 'h3')], [
      yolDY('Kerem, millî bayramlar hakkında bir yol bulmaca çözüyor.', [['Millî bayramlar tarihimizdeki önemli olayları hatırlatır.', true], ['23 Nisan\'ı Atatürk dünya çocuklarına armağan etmiştir.', true], ['Zafer Bayramı, Cumhuriyet\'in ilanından sonraki bir olayı kutlar.', false]], 'h4'),
      kapDY('Dedesiyle konuşan Defne, eski bayramlarla ilgili öğrendiklerini kartlara yazdı. Öğretmen kartları doğruluğuna göre kaplara atıyor.', [
        ['Eskiden de bayramlarda evlere bayrak asılırdı.', true], ['Fener alayı bayram geleneklerimizden biridir.', true], ['Eskiden bayramlarda tören yapılmazdı.', false], ['Bayram gelenekleri kuşaktan kuşağa aktarılır.', true]], 'h5'),
      coktan(p('Okul, 29 Ekim için gösteri hazırlıyor: 4-A şiir okuyacak, 4-B halk oyunu oynayacak, 4-C sergi panosu hazırlayacak. Gösteri saatinde 4-B\'nin müziği çalışmadı; 4-A öğrencileri hemen bir marş söyleyerek boşluğu doldurdu.'),
        'Bu olayda 4-A öğrencilerinin davranışı en çok hangi değeri gösterir?', 'Dayanışma', ['Kıskançlık', 'Bencillik', 'Sabırsızlık'])]]),

    'hafta-08': W(8, 2, 'Geçmişten Bugüne Oyunlar', 'Geçmiş ve bugün: oyunlar ve oyuncaklar', () => [[
      ortak(p('Okulda dedeler ve torunlar en sevdikleri oyunu işaretledi.') + grafik('En sevilen oyunlar', ['Saklambaç', 'Seksek', 'Futbol', 'Bilgisayar', 'Körebe'], [9, 7, 8, 6, 4], 'Kişi', '#12b886'), [
        () => coktan('', 'Saklambaç, seksek ve körebeyi seçenlerin toplamı kaçtır?', '20', ['16', '18', '22']),
        () => coktan('', 'Grafikteki oyunlardan hangisi dedelerin çocukluğunda oynanamazdı?', 'Bilgisayar oyunu', ['Saklambaç', 'Futbol', 'Körebe'])]),
      roma(p('Oyuncaklar zamanla değişmiştir: Dedemin çocukluğunda bez bebek ve tahta araba, annemin çocukluğunda plastik bebek ve misket, bugün ise uzaktan kumandalı arabalar ve tabletler yaygındır.'),
        'Bu bilgilere göre aşağıdaki yargılardan hangileri doğrudur?', [['Oyuncakların yapıldığı malzemeler değişmiştir.', true], ['Teknolojinin gelişmesi oyuncakları etkilemiştir.', true], ['Bugün hiç kimse misketle oynamaz.', false]]),
      sirala('Seksek oyununun kuralları karışık verilmiştir.', ['Yere numaralı kareler çizilir.', 'Taş ilk kareye atılır.', 'Taşın olduğu kareye basmadan tek ayakla zıplanır.', 'Dönüşte taş alınarak başlangıca gelinir.', 'Taş bir sonraki kareye atılır.'], 'Oyunun kuralları doğru sırayla hangisidir?', 'i3'),
      bulmaca('Öğrenciler "oyunlar ve oyuncaklar" bulmacasını çözüyor.', [['Eski oyuncakların çoğunun yapıldığı malzeme.', 'TAHTA'], ['Çocukların oynamak için kullandığı eşya.', 'OYUNCAK'], ['Bugünkü oyuncakların çoğunun malzemesi.', 'PLASTİK'], ['Birlikte oyun oynadığımız kişi.', 'ARKADAŞ'], ['Eskiden çubukla yuvarlanan halka oyuncak.', 'ÇEMBER']], 'i4')], [
      esle('Geleneksel oyunlar ve kuralları karışık verilmiştir.', [['Saklambaç', 'Ebe gözlerini kapatıp sayar, diğerleri saklanır.'], ['Körebe', 'Gözleri bağlı ebe arkadaşlarını yakalamaya çalışır.'], ['Seksek', 'Yere çizilen karelerde tek ayakla zıplanır.'], ['Mendil kapmaca', 'İki takım ortadaki mendili kapmaya çalışır.']], 'Buna göre oyunlarla kuralların doğru eşleştirilmesi hangisidir?', 'i5'),
      coktan(p('Okulda "Geleneksel Oyunlar Haftası" düzenlendi. Öğrenciler aile büyüklerinden öğrendikleri oyunları teneffüslerde oynadı. Hafta sonunda yapılan ankette öğrencilerin çoğu bu oyunları çok eğlenceli bulduğunu söyledi.'),
        'Bu etkinliğin en önemli sonucu hangisidir?', 'Geleneksel oyunların unutulmadan yaşatılmasına katkı sağlanması', ['Tablet kullanımının tamamen bitmesi', 'Teneffüslerin kısalması', 'Oyunların yalnız aile büyüklerince oynanması']),
      coktan(p('Ece, dedesinin çocukken yaptığı tahta arabayı ve kendi uzaktan kumandalı arabasını karşılaştırıyor.'), 'Bu iki oyuncağın ortak özelliği aşağıdakilerden hangisidir?', 'İkisinin de çocukların oynaması için yapılmış olması', ['İkisinin de pille çalışması', 'İkisinin de plastikten yapılması', 'İkisinin de fabrikada üretilmesi'])]]),

    'hafta-09': W(9, 2, 'Atatürk\'ü Tanıyorum', 'Atatürk\'ün hayatı ve kişilik özellikleri', () => [[
      ortak(p('Atatürk\'ün hayatından bazı olaylar zaman şeridinde gösterilmiştir.') + serit([['1881', 'Selanik\'te doğdu'], ['1893', 'Askerî okula girdi'], ['1919', 'Samsun\'a çıktı'], ['1920', 'TBMM açıldı'], ['1923', 'Cumhuriyet'], ['1938', 'Vefat etti']]), [
        () => coktan('', 'Atatürk Samsun\'a çıktığında kaç yaşındaydı?', '38', ['36', '37', '39']),
        () => coktan('', 'Cumhuriyet\'in ilanı ile Atatürk\'ün vefatı arasında kaç yıl vardır?', '15', ['13', '17', '19'])]),
      kacTane(p('Atatürk küçükken babası ölünce bir süre çiftlikte yaşadı. Tarladaki kargaları kovma işini kardeşiyle nöbetleşerek düzenledi. Okulda matematik dersinde o kadar başarılıydı ki öğretmeni ona "Kemal" adını verdi. Okuduğu kitapların kenarına notlar alırdı.') + p('Öğrenciler bu metinden Atatürk\'ün kişilik özellikleriyle ilgili çıkarımlar yaptı:'), [
        ['Sorumluluk sahibiydi.', true], ['Çalışkan ve başarılıydı.', true], ['Kitap okumayı sevmezdi.', false], ['Sorunlara planlı çözümler bulurdu.', true]]),
      kareYol('Ada, Atatürk\'le ilgili bilgilerin doğruluğuna göre karelerde ilerliyor.', [['Atatürk 1881\'de Selanik\'te doğdu.', true], ['TBMM, Cumhuriyet\'ten sonra açıldı.', false], ['10 Kasım\'da Atatürk\'ü anarız.', true], ['Atatürk 19 Mayıs\'ı çocuklara armağan etti.', false]], 'j3')], [
      tabloSec(p('Öğretmen, Atatürk\'ün kişilik özelliklerini gösteren davranışları tahtaya yazdı.'), 'Davranışlar hangi seçenekte kişilik özellikleriyle doğru eşleştirilmiştir?',
        ['Zor şartlarda vazgeçmedi.', 'Bilime önem verdi.', 'Ülkesi için çalıştı.'], ['Kararlılık', 'İleri görüşlülük', 'Vatanseverlik'], [['Vatanseverlik', 'Kararlılık', 'İleri görüşlülük'], ['İleri görüşlülük', 'Vatanseverlik', 'Kararlılık'], ['Kararlılık', 'Vatanseverlik', 'İleri görüşlülük']], 'j4'),
      cocukSec(p('"Hayatta en hakiki mürşit (yol gösterici) ilimdir (bilimdir)." — Atatürk') + p('Öğrenciler bu sözü yorumladı.'), 'Hangi öğrencinin yorumu bu söze uygun değildir?',
        ['Doğru yolu bulmak için şansımıza güvenmeliyiz.', 'Bir konuda karar verirken bilimsel bilgiye başvurmalıyız.', 'Söylentilere değil, araştırmaya güvenmeliyiz.', 'Bilim insanlarının çalışmaları bize yol gösterir.'], 'j5'),
      coktan(p('Atatürk, yeni harfler kabul edildikten sonra yurdun birçok yerine giderek kara tahta başında halka okuma yazma öğretti. Bu yüzden ona "Başöğretmen" denir.'), 'Bu bilgi Atatürk\'ün en çok hangi alana önem verdiğini gösterir?', 'Eğitim', ['Spor', 'Ticaret', 'Tarım'])]]),

    'hafta-10': W(10, 2, 'Millî Mücadele Kahramanları', 'Millî Mücadele\'de kahramanlar', () => [[
      ortak(p('Millî Mücadele\'de kahramanlık gösteren bazı kişiler aşağıda verilmiştir.') + tablo(['Kahraman', 'Şehir', 'Ne yaptı?'], [['Nene Hatun', 'Erzurum', 'Aziziye Tabyası\'nın savunmasına katıldı.'], ['Şerife Bacı', 'Kastamonu', 'Kar fırtınasında cepheye cephane taşıdı.'], ['Sütçü İmam', 'Kahramanmaraş', 'Halkın direnişini başlattı.'], ['Şahin Bey', 'Gaziantep', 'Şehrin savunmasında kahramanlık gösterdi.']]), [
        () => coktan('', 'Tabloya göre Millî Mücadele ile ilgili hangisi söylenebilir?', 'Kadın erkek bütün halk mücadeleye katılmıştır.', ['Yalnız askerler savaşmıştır.', 'Mücadele tek bir şehirde olmuştur.', 'Halk mücadeleye ilgisiz kalmıştır.']),
        () => coktan('', '"Kahraman" ve "Gazi" unvanları tablodaki hangi şehirlere verilmiştir?', 'Kahramanmaraş ve Gaziantep', ['Erzurum ve Kastamonu', 'Kastamonu ve Gaziantep', 'Erzurum ve Kahramanmaraş'])]),
      kodDY('Öğrenciler Millî Mücadele ile ilgili bilgileri değerlendiriyor.', [
        ['Millî Mücadele\'de kadınlar cepheye cephane taşıdı.', true], ['Çocuklar Millî Mücadele\'de hiçbir görev almadı.', false], ['Kağnılar cepheye malzeme taşımada kullanıldı.', true], ['Millî Mücadele 1923\'te başladı.', false]], 'k2'),
      yolDY('Arda, Millî Mücadele hakkındaki ifadeleri değerlendirerek ilerliyor.', [['Şerife Bacı Erzurum\'da savaştı.', false], ['Atatürk 1919\'da Samsun\'a çıkarak mücadeleyi başlattı.', true], ['Nene Hatun Erzurum\'un savunmasına katıldı.', true]], 'k3')], [
      konusma('Öğrenciler Millî Mücadele\'de birlik ve beraberlik üzerine konuşuyor.', [
        ['Defne', 'Mücadeleyi milletin birlik olması kazandırdı.', true], ['Can', 'Yalnızca büyük şehirlerdeki insanlar mücadeleye katıldı.', false],
        ['Elif', 'Cepheye malzeme taşıyanlar arasında çocuklar da vardı.', true], ['Bora', 'Millî Mücadele\'de herkes yalnız kendi şehrini düşündü.', false]], 'k4'),
      kapDY('Kerem, Millî Mücadele kahramanlarıyla ilgili kartlar hazırladı.', [
        ['Nene Hatun Erzurumludur.', true], ['Şahin Bey Gaziantep\'in savunmasında kahramanlık göstermiştir.', true], ['Sütçü İmam Kastamonu\'da direniş başlatmıştır.', false], ['Şerife Bacı cepheye cephane taşımıştır.', true]], 'k5'),
      coktan(p('Kağnılar gıcırdar karlı yollarda, / Analar mermi taşır kucaklarda. / Bir olur, iri olur bu millet, / Bayrağı dalgalanır doruklarda.'), 'Bu dizelerde en çok hangi duygu vurgulanmıştır?', 'Birlik ve kararlılık', ['Korku ve vazgeçme', 'Neşe ve eğlence', 'Kıskançlık'])]]),

    'hafta-11': W(11, 2, 'Kültürel Mirasımız', 'Yakın çevredeki tarihî ve kültürel mekânlar', () => [[
      ortak(p('Bir ailenin ziyaret etmek istediği müzenin bilgileri:') + etiket([['Müze', 'Arkeoloji Müzesi'], ['Açık', 'Salı - Pazar, 09.00-17.00'], ['Kapalı', 'Pazartesi'], ['Öğrenci', 'Ücretsiz'], ['Yetişkin', '60 TL'], ['65 yaş ve üstü', 'Ücretsiz']]), [
        () => coktan('', 'Anne, baba, 70 yaşındaki dede ve iki öğrenci çocuk müzeye toplam kaç TL öder?', '120', ['60', '180', '300']),
        () => coktan('', 'Aile müzeyi hangi gün ziyaret edemez?', 'Pazartesi', ['Salı', 'Cuma', 'Pazar'])]),
      roma(p('Kültürel miras yalnız yapılardan oluşmaz. Ebru sanatı, Karagöz, âşıklık geleneği ve kahve kültürü gibi gelenekler de korunması gereken mirasımızdır.'),
        'Buna göre aşağıdakilerden hangileri somut olmayan (elle tutulamayan) kültürel mirasa örnektir?', [['Âşıkların söylediği türküler', true], ['Selimiye Camii', false], ['Karagöz oyunu', true]]),
      sirala('Tarihî bir köprünün onarılması için yapılacaklar karışık verilmiştir.', ['Köprünün eski fotoğrafları ve belgeleri incelenir.', 'Uzmanlar hasarları belirler.', 'Eski yapıya uygun malzemeler seçilir.', 'Onarım yapılır ve köprü ziyarete açılır.'], 'Doğru sıralama hangisidir?', 'l3'),
      bulmaca('"Kültürel mirasımız" bulmacası:', [['Eski eserlerin sergilendiği yer.', 'MÜZE'], ['Galata Kulesi\'nin bulunduğu şehir.', 'İSTANBUL'], ['Eski yapıların aslına uygun onarılması.', 'RESTORASYON'], ['Kazı yaparak geçmişi araştıran bilim insanı.', 'ARKEOLOG'], ['Mimar Sinan\'ın Edirne\'deki camisi.', 'SELİMİYE']], 'l4')], [
      esle('Türkiye\'deki bazı kültürel miras ögeleri ve bulundukları şehirler karışık verilmiştir.', [['Efes Antik Kenti', 'İzmir'], ['Selimiye Camii', 'Edirne'], ['Sümela Manastırı', 'Trabzon'], ['Göbeklitepe', 'Şanlıurfa']], 'Doğru eşleştirme hangisidir?', 'l5'),
      coktan(p('Tarihî bir köprünün taşlarına isimler kazınmış, çevresine çöp atılmıştı. Belediye köprünün çevresine uyarı levhaları koydu, temizlik yaptı ve okullarla birlikte "Mirasımıza Sahip Çıkalım" kampanyası başlattı.'), 'Belediyenin kampanyayı okullarla birlikte yapmasının en önemli nedeni hangisidir?', 'Gelecek kuşakların da kültürel mirası koruma bilinci kazanması', ['Köprünün yeniden yapılması', 'Okulların tatil olması', 'Levhaların daha ucuza yapılması']),
      coktan(p('Ayşe, ninesinin ona öğrettiği yöresel bir türküyü okuldaki kültür gecesinde söyledi.'), 'Ayşe\'nin bu davranışı en çok hangisine katkı sağlar?', 'Somut olmayan kültürel mirasın yaşatılmasına', ['Tarihî yapıların onarılmasına', 'Müzelerin genişlemesine', 'Kazı çalışmalarına'])]]),

    'hafta-12': W(12, 3, 'Ana ve Ara Yönler', 'Ana ve ara yönler', () => [[
      ortak(p('Okul bahçesinin planı aşağıda verilmiştir. Kuzey yukarıdadır.') + tablo(['', 'Batı', 'Orta', 'Doğu'], [['Kuzey', 'Kantin', 'Bayrak direği', 'Kütüphane'], ['Orta', 'Bahçe', 'Okul binası', 'Spor salonu'], ['Güney', 'Otopark', 'Ana kapı', 'Oyun alanı']], '#12b886'), [
        () => coktan('', 'Kantin, okul binasının hangi yönündedir?', 'Kuzeybatı', ['Kuzeydoğu', 'Güneybatı', 'Güneydoğu']),
        () => coktan('', 'Oyun alanından kütüphaneye giden bir öğrenci hangi yöne yürür?', 'Kuzey', ['Güney', 'Doğu', 'Batı'])]),
      kacTane(p('Ahmet sabah okula giderken Güneş\'in tam karşısından doğduğunu fark etti.') + p('Ahmet\'in arkadaşları şu yorumları yaptı:'), [
        ['Ahmet sabah doğuya doğru yürümektedir.', true], ['Akşam eve dönerken Güneş Ahmet\'in önünde olur.', true], ['Sabah Ahmet\'in sağ tarafı güneydir.', true], ['Sabah Ahmet\'in sol tarafı batıdır.', false]]),
      kareYol('Su, yönlerle ilgili bilgileri değerlendiriyor.', [['Kuzey ile doğu arasındaki ara yön kuzeydoğudur.', true], ['Güneş batıdan doğar.', false], ['Dört ana yön vardır.', true], ['Güneybatı bir ana yöndür.', false], ['Pusulanın ibresi kuzeyi gösterir.', true]], 'm3')], [
      tabloSec(p('Bir öğrenci pusula gülünün ortasında duruyor ve yüzü kuzeye dönük.'), 'Öğrencinin sağı, solu ve arkası hangi yönlerdir?',
        ['Sağı', 'Solu', 'Arkası'], ['Doğu', 'Batı', 'Güney'], [['Batı', 'Doğu', 'Güney'], ['Doğu', 'Güney', 'Batı'], ['Güney', 'Batı', 'Doğu']], 'm4'),
      cocukSec(p('Öğrenciler sınıfta yön bulma yollarını konuşuyor.'), 'Hangi öğrencinin söylediği yanlıştır?',
        ['Ağaçların yosunlu tarafı her zaman güneydir.', 'Pusula ile yön bulabiliriz.', 'Güneş\'in doğduğu yön doğudur.', 'Gece Kutup Yıldızı kuzeyi gösterir.'], 'm5'),
      coktan(p('Ankara\'dan yola çıkan bir aile önce kuzeye, sonra batıya giderek bir şehre ulaştı.'), 'Bu ailenin ulaştığı şehir Ankara\'nın hangi yönünde olabilir?', 'Kuzeybatı', ['Güneydoğu', 'Güneybatı', 'Doğu'])]]),

    'hafta-13': W(13, 3, 'Kroki Çiziyorum', 'Kroki çizme ve okuma', () => [[
      ortak(p('Ela, mahallesinin krokisini kareli kâğıda çizdi. Her kare bir sokak boyudur. Kuzey yukarıdadır.') + tablo(['', '1. sütun', '2. sütun', '3. sütun', '4. sütun'], [['1. satır', 'Ev', '', 'Park', ''], ['2. satır', '', 'Cami', '', 'Fırın'], ['3. satır', 'Okul', '', 'Market', '']], '#12b886'), [
        () => coktan('', 'Krokiye göre ev, okulun hangi yönündedir?', 'Kuzey', ['Güney', 'Doğu', 'Batı']),
        () => coktan('', 'Marketten çıkan Ela önce 1 kare doğuya, sonra 1 kare kuzeye gidiyor. Ela nereye ulaşır?', 'Fırın', ['Park', 'Cami', 'Ev'])]),
      kodDY('Öğrenciler kroki ile ilgili bilgileri değerlendiriyor.', [
        ['Kroki, bir yerin kuşbakışı çizilmiş basit planıdır.', true], ['Krokide ölçek kullanmak zorunludur.', false], ['Krokide kuzey yönü gösterilir.', true], ['Krokiler yalnızca bilgisayarla çizilir.', false]], 'n2'),
      yolDY('Can, kroki bilgileriyle yol bulma oyunu oynuyor.', [['Krokide kullanılan işaretler bir tabloda açıklanır.', true], ['Kroki çizerken yerleri yandan görünüşleriyle çizeriz.', false], ['Krokiyle bir yere nasıl gidileceğini anlatabiliriz.', true]], 'n3')], [
      konusma('Öğrenciler sınıflarının krokisini çizmeden önce konuşuyor.', [
        ['Ada', 'Önce sınıfın kapısını ve pencerelerini yerleştirmeliyiz.', true], ['Efe', 'Sıraları yukarıdan bakar gibi küçük dikdörtgenlerle çizebiliriz.', true],
        ['Su', 'Krokiye kuzey yönünü yazmamıza gerek yok.', false], ['Kaan', 'Kullandığımız işaretleri bir tabloda göstermeliyiz.', true]], 'n4'),
      kapDY('Öğretmen kroki okuma ile ilgili kartları kaplara atıyor.', [
        ['Krokiler gerçek boyutlarıyla çizilir.', false], ['Krokide yönler kuzey işaretine göre bulunur.', true], ['Kroki çizmek için uzman olmak gerekir.', false], ['Kroki, kaybolmamamıza yardımcı olabilir.', true]], 'n5'),
      coktan(p('Kerem, arkadaşına evinin yolunu şöyle tarif etti: "Okuldan çıkınca doğuya yürü. İlk sokaktan kuzeye dön. Sağında parkı, solunda eczaneyi göreceksin. Parkın karşısındaki mavi bina bizim ev."'), 'Kerem\'in tarifine göre eczane, parkın hangi yönündedir?', 'Batı', ['Doğu', 'Kuzey', 'Güney'])]]),

    'hafta-14': W(14, 3, 'Yeryüzü Şekilleri', 'Yeryüzü şekilleri', () => [[
      ortak(p('Bir gezi günlüğü: "Yolculuğumuz denize kadar uzanan geniş ve düz bir arazide başladı. Sonra zirveleri karlı, yüksek bir yere tırmandık. İki dağ arasında akarsuyun oyduğu derin bir yerden geçtik. En son dört yanı denizle çevrili küçük bir kara parçasına vapurla gittik."'), [
        () => coktan('', 'Gezinin başladığı ve bittiği yerler hangi yeryüzü şekilleridir?', 'Ova - Ada', ['Plato - Yarımada', 'Ova - Yarımada', 'Vadi - Ada']),
        () => coktan('', 'Günlükte hangi yeryüzü şeklinden söz edilmemiştir?', 'Plato', ['Dağ', 'Vadi', 'Ova'])]),
      roma(p('Aşağıdaki tabloda üç köyün bulunduğu yer ve nüfusu verilmiştir.') + tablo(['Köy', 'Yeryüzü şekli', 'Nüfus'], [['A', 'Akarsu kenarında ova', 'Çok kalabalık'], ['B', 'Yüksek dağ yamacı', 'Az'], ['C', 'Ova', 'Kalabalık']]), 'Tabloya göre aşağıdaki yargılardan hangileri çıkarılabilir?', [['İnsanlar düz yerleri yerleşim için tercih eder.', true], ['Suya yakınlık yerleşmeyi etkiler.', true], ['Dağ yamaçlarında hiç yerleşim yoktur.', false]]),
      sirala('Bir akarsuyun yolculuğu karışık verilmiştir.', ['Dağlarda kar ve yağmur suları toplanır.', 'Su, dağın yamaçlarından aşağı akar.', 'Akarsu iki dağ arasında vadi oluşturur.', 'Akarsu ovaya ulaşıp yavaşlar.', 'Akarsu denize dökülür.'], 'Akarsuyun yolculuğu doğru sırayla hangisidir?', 'o3'),
      bulmaca('Yeryüzü şekilleri bulmacası:', [['Yerden kendiliğinden çıkan su kaynağı.', 'PINAR'], ['Yanardağdan çıkan erimiş kaya.', 'LAV'], ['Dört yanı suyla çevrili kara parçası.', 'ADA'], ['Dağdan alçak, küçük yükselti.', 'TEPE'], ['Geniş ve düz arazi.', 'OVA']], 'o4')], [
      esle('Bazı yeryüzü şekilleri ve tanımları karışık verilmiştir.', [['Yarımada', 'Üç yanı suyla çevrili kara'], ['Plato', 'Yüksekte bulunan geniş düzlük'], ['Körfez', 'Denizin karaya doğru sokulduğu yer'], ['Vadi', 'Akarsuyun oyduğu uzun çukur']], 'Doğru eşleştirme hangisidir?', 'o5'),
      coktan(p('Ece, Türkiye haritasında Ağrı Dağı\'nı, Çukurova\'yı ve Kapadokya\'daki peribacalarını işaretledi.'), 'Bu yerlerle ilgili aşağıdakilerden hangisi doğrudur?', 'Çukurova\'da tarım yapmak Ağrı Dağı\'nın zirvesinden daha kolaydır.', ['Ağrı Dağı bir ovadır.', 'Çukurova Türkiye\'nin en yüksek yeridir.', 'Peribacaları denizin altındadır.']),
      coktan(p('Bir köyün çevresi dik ve yüksek dağlarla çevrilidir. Köyde düz arazi azdır.'), 'Bu köyde yaşayanların en çok hangi ekonomik etkinliği yapması beklenir?', 'Hayvancılık', ['Gemicilik', 'Geniş tarlalarda buğday tarımı', 'Deniz turizmi'])]]),

    'hafta-15': W(15, 3, 'Hava Durumu ve Yaşam', 'Hava durumu ve insan yaşamı', () => [[
      kacTane(p('Bir şehrin haftalık hava tahmini:') + tablo(['Gün', 'Hava', 'Sıcaklık'], [['Pazartesi', 'Güneşli', '22 °C'], ['Salı', 'Parçalı bulutlu', '19 °C'], ['Çarşamba', 'Yağmurlu', '14 °C'], ['Perşembe', 'Sağanak', '12 °C'], ['Cuma', 'Güneşli', '18 °C']]) + p('Tabloyu inceleyen öğrenciler şunları söyledi:'), [
        ['Açık havada piknik için en uygun gün pazartesidir.', true], ['Perşembe günü şemsiye almak gerekir.', true], ['Pazartesi ile perşembe arasındaki sıcaklık farkı 8 °C\'dir.', false], ['Hafta boyunca sıcaklık hep düşmüştür.', false]]),
      grafikSec(p('Defne, bir hafta boyunca her gün öğle saatinde termometreye bakıp sıcaklığı yazdı: Pazartesi 20, salı 16, çarşamba 12, perşembe 14, cuma 18 derece.'), 'Defne\'nin ölçümlerini gösteren grafik hangisidir?', ['Pzt', 'Sal', 'Çar', 'Per', 'Cum'], [20, 16, 12, 14, 18], [[20, 12, 16, 14, 18], [12, 14, 16, 18, 20], [20, 16, 14, 12, 18]], 'p2', '°C'),
      kareYol('Mert, hava durumu bilgileriyle kare oyunu oynuyor.', [['Hava durumu kısa sürede değişebilir.', true], ['Termometre yağış miktarını ölçer.', false], ['Hava durumu giyimimizi etkiler.', true], ['Don olayı sıcak yaz günlerinde olur.', false]], 'p3')], [
      tabloSec(p('İzmir\'de yaşayan Ece, kışın Erzurum\'daki dedesini, yazın Antalya\'daki teyzesini ziyaret edecek. Erzurum\'da kış -10 °C, Antalya\'da yaz 35 °C olacak.'), 'Ece\'nin yanına alması gereken giysiler hangi seçenekte doğru verilmiştir?', ['Erzurum (kış)', 'Antalya (yaz)'], ['Kalın mont, bere', 'Şapka, ince tişört'], [['Şapka, ince tişört', 'Kalın mont, bere'], ['Yağmurluk, sandalet', 'Kalın mont, bere'], ['Kalın mont, bere', 'Kazak, bot']], 'p4'),
      cocukSec(p('Çiftçi Hasan Amca, televizyonda yarın don olacağını duydu. Seradaki fidelerin üzerini örttü ve sobayı yaktı.') + p('Öğrenciler bu olayı yorumladı.'), 'Hangi öğrencinin yorumu yanlıştır?',
        ['Hava tahminleri çiftçiler için önemsizdir.', 'Hava durumu tarımı etkiler.', 'Hasan Amca tahmine göre önlem almıştır.', 'Don, fidelere zarar verebilir.'], 'p5'),
      coktan(p('Bir okul, yarın kuvvetli rüzgâr ve sağanak beklendiği için bahçedeki spor şenliğini kapalı spor salonuna taşıdı.'), 'Okulun bu kararı aşağıdakilerden hangisini gösterir?', 'Hava durumunun etkinlik planlarını etkilediğini', ['Spor şenliklerinin gereksiz olduğunu', 'Rüzgârın hiçbir zararı olmadığını', 'Hava tahminlerinin her zaman yanlış olduğunu'])]]),

    'hafta-16': W(16, 3, 'Doğal Afetler', 'Doğal afetler', () => [[
      ortak(p('Bir gazetede yer alan haber başlıkları:') + tablo(['No', 'Haber'], [['1', 'Yer kabuğundaki kırılmayla şehir sarsıldı.'], ['2', 'Şiddetli yağmurdan sonra dere taştı, evleri su bastı.'], ['3', 'Eğimli yamaçta toprak kayarak yolu kapattı.'], ['4', 'Dağdan kopan kar kütlesi köy yolunu kapattı.']]), [
        () => coktan('', 'Haberlerde anlatılan afetler sırasıyla hangi seçenekte verilmiştir?', 'Deprem, sel, heyelan, çığ', ['Sel, deprem, çığ, heyelan', 'Deprem, heyelan, sel, çığ', 'Heyelan, sel, deprem, çığ']),
        () => coktan('', 'Bu afetlerden hangisinin ne zaman olacağı önceden bilinemez?', 'Deprem', ['Sel', 'Çığ', 'Hepsinin zamanı tam olarak bilinir.'])]),
      kodDY('Öğrenciler doğal afetlerle ilgili kartları değerlendiriyor.', [
        ['Ağaçlandırma sel ve heyelanı azaltır.', true], ['Deprem anında asansöre binmeliyiz.', false], ['Dere yataklarına ev yapmak sel riskini artırır.', true], ['Afetler yalnızca kış mevsiminde olur.', false]], 'r2'),
      yolDY('Elif, deprem anında yapılacaklarla ilgili yol oyunu oynuyor.', [['Deprem anında "çök, kapan, tutun" yapılır.', true], ['Deprem anında pencere ve camlardan uzak durulur.', true], ['Deprem bittikten sonra toplanma alanına gidilir.', true]], 'r3')], [
      konusma('Bir köyün yamaçlarındaki ağaçlar kesildi. Birkaç yıl sonra yağmurlarda sel ve heyelan olayları arttı. Öğrenciler bu durumu yorumladı.', [
        ['Can', 'Ağaç kökleri toprağı tuttuğu için ağaçlar heyelanı azaltır.', true], ['Ece', 'Ağaç kesmenin sel ile hiçbir ilgisi yoktur.', false],
        ['Bora', 'Yamaçlara yeniden ağaç dikmek bir çözüm olabilir.', true], ['Ada', 'Yağmur yağmazsa bile heyelan her gün olur.', false]], 'r4'),
      kapDY('AFAD gönüllüsü, okulda öğrencilerin hazırladığı kartları kaplara atıyor.', [
        ['Afet çantası hazırlamak afet öncesi yapılır.', true], ['Toplanma alanını önceden öğrenmeliyiz.', true], ['Depremde merdivenlere koşmalıyız.', false], ['Afetten sonra yetkililerin uyarılarını dinleriz.', true], ['Selde araçla sulara girilebilir.', false]], 'r5', 'doğru'),
      coktan(p('Okulda deprem tatbikatı yapıldı. Alarm çaldığında öğrenciler sıralarının yanında çök-kapan-tutun yaptı, sarsıntı bitince öğretmenlerinin önderliğinde bahçedeki toplanma alanına yürüdü. Bir öğrenci ise çantasını almak için sınıfa geri döndü.'), 'Tatbikatta yanlış davranan öğrenci için hangisi söylenebilir?', 'Eşyası için kendini tehlikeye atmıştır.', ['Toplanma alanına doğru şekilde gitmiştir.', 'Öğretmeninin uyarılarını dinlemiştir.', 'Çök-kapan-tutun yapmayı unutmuştur.'])]]),

    'hafta-17': W(17, 3, 'Afetlere Hazırım', 'Afetlere hazırlık', () => [[
      ortak(p('Kerem\'in ailesi afet çantasını hazırladı.') + tablo(['Malzeme', 'Amacı'], [['Su ve konserve', 'Beslenme'], ['El feneri ve pil', 'Aydınlanma'], ['Düdük', 'Yerini bildirme'], ['İlk yardım çantası', 'Yaralanmalar'], ['Kimlik fotokopisi', 'Kimlik belirleme']]), [
        () => coktan('', 'Enkaz altında kalan biri sesini duyurmak için hangi malzemeyi kullanmalıdır?', 'Düdük', ['El feneri', 'Konserve', 'Kimlik fotokopisi']),
        () => coktan('', 'Afet çantasının nerede durması en doğrudur?', 'Kolayca ulaşılabilen bir yerde', ['Kilitli bir dolabın içinde', 'Bodrum katta', 'Komşunun evinde'])]),
      roma(p('AFAD, okulların yanında toplanma alanları belirlemiştir. Bu alanlar, yeşil zemin üzerinde insan şekilleri olan levhalarla gösterilir.'), 'Toplanma alanlarıyla ilgili aşağıdakilerden hangileri doğrudur?', [['Afetten sonra güvenle bir araya gelmek için kullanılır.', true], ['Levhalar sayesinde kolayca bulunabilir.', true], ['Araç park etmek için kullanılır.', false]]),
      sirala('Bir ailenin afet planı hazırlarken yaptıkları karışık verilmiştir.', ['Evdeki tehlikeli eşyaları belirlemek', 'Dolapları duvara sabitlemek', 'Afet çantasını hazırlamak', 'Toplanma alanını birlikte ziyaret etmek'], 'Planın adımları doğru sırayla hangisidir?', 's3'),
      bulmaca('Afetlere hazırlık bulmacası:', [['Doğal olayların zarar vermesi.', 'AFET'], ['Karanlıkta yolumuzu aydınlatan el aracı.', 'FENER'], ['112 … Çağrı Merkezi', 'ACİL'], ['Enkaz altında sesimizi duyurur.', 'DÜDÜK']], 's4')], [
      esle('Afet anındaki durumlar ve yapılması gerekenler karışık verilmiştir.', [['Depremde sınıftaysak', 'Sıranın yanında çök-kapan-tutun yaparız.'], ['Sel sırasında', 'Yüksek ve güvenli yerlere çıkarız.'], ['Yangında duman varsa', 'Yere eğilerek ilerleriz.'], ['Deprem bittiğinde', 'Toplanma alanına gideriz.']], 'Doğru eşleştirme hangisidir?', 's5'),
      coktan(p('Bir ailenin evinde kitaplık ve dolaplar duvara sabitlenmemiş, yatakların üstünde ağır bir raf bulunuyor.'), 'Bu aile depreme hazırlık için öncelikle ne yapmalıdır?', 'Dolapları sabitleyip ağır rafı yatağın üstünden kaldırmalıdır.', ['Yeni dolap almalıdır.', 'Odayı boyamalıdır.', 'Hiçbir şey yapmasına gerek yoktur.']),
      coktan(p('Okulda yılda iki kez afet tatbikatı yapılıyor. İlk tatbikatta binanın boşaltılması 6 dakika, ikincisinde 4 dakika sürdü.'), 'Bu bilgiye göre tatbikatların en önemli yararı hangisidir?', 'Öğrencilerin ne yapacaklarını öğrenip daha hızlı davranması', ['Derslerin kısalması', 'Okulun daha kalabalık olması', 'Afetlerin tamamen önlenmesi'])]]),

    'hafta-18': W(18, 4, 'Teknoloji Değişiyor', 'Teknolojik ürünlerin geçmişi ve bugünü', () => [[
      kacTane(p('İletişim araçlarının değişimi bir zaman şeridinde verilmiştir.') + serit([['Eskiden', 'Mektup, ulak'], ['1800\'ler', 'Telgraf'], ['1900\'ler', 'Telefon, radyo'], ['1990\'lar', 'Cep telefonu'], ['Bugün', 'Görüntülü görüşme']]) + p('Bu zaman şeridi için şu yorumlar yapıldı:'), [
        ['İletişim zamanla hızlanmıştır.', true], ['Telefon, telgraftan önce bulunmuştur.', false], ['Bugün uzaktaki biriyle görüntülü konuşabiliriz.', true], ['Mektup bugün hiç kullanılmaz.', false]]),
      tabloSec(p('Dedesi Kaan\'a çocukluğunda kullandıkları araçları anlattı.'), 'Dedesinin kullandığı araçların bugünkü karşılıkları hangi seçenekte doğru verilmiştir?', ['Gaz lambası', 'Tokaç', 'At arabası'], ['Ampul', 'Çamaşır makinesi', 'Otomobil'], [['Çamaşır makinesi', 'Ampul', 'Otomobil'], ['Ampul', 'Otomobil', 'Çamaşır makinesi'], ['Otomobil', 'Çamaşır makinesi', 'Ampul']], 't2'),
      kareYol('Su, teknolojinin geçmişiyle ilgili bilgileri değerlendiriyor.', [['Teknoloji insanlara zaman kazandırır.', true], ['Radyo, internetten sonra bulunmuştur.', false], ['Teknolojik ürünler zamanla gelişir.', true], ['Eskiden çamaşırlar makinede yıkanırdı.', false], ['Teknolojinin olumsuz etkileri de olabilir.', true]], 't3')], [
      cocukSec(p('Öğrenciler teknolojinin günlük yaşama etkilerini konuşuyor.'), 'Hangi öğrencinin söylediği yanlıştır?', ['Teknolojinin hiçbir olumsuz etkisi yoktur.', 'Teknoloji iletişimi kolaylaştırmıştır.', 'Teknolojik ürünler bilinçli kullanılmalıdır.', 'Bazı işler eskisine göre daha kısa sürer.'], 't4'),
      ortak(p('Eskiden çamaşırlar dere kenarında tokaçla yıkanır ve bütün gün sürerdi. Bugün çamaşır makinesiyle 1-2 saatte yıkanıyor. Ancak eski makineler çok su ve elektrik harcarken yeni makineler daha az harcıyor.'), [
        () => coktan('', 'Metne göre teknolojinin günlük yaşama etkisi hangisidir?', 'İnsanlara zaman kazandırmıştır.', ['Çamaşırları daha kirli yapmıştır.', 'Suyu gereksiz kılmıştır.', 'Dereleri kurutmuştur.']),
        () => coktan('', 'Yeni makinelerin daha az su ve elektrik harcaması en çok hangisine katkı sağlar?', 'Doğal kaynakların korunmasına', ['Çamaşırların renginin değişmesine', 'Makinelerin pahalanmasına', 'Derelerin taşmasına'])]),
      coktan(p('Bir müzede "Telefonun Hikâyesi" sergisi var: duvar telefonu, çevirmeli telefon, tuşlu telefon, cep telefonu ve akıllı telefon sırayla diziliyor.'), 'Bu sergiden çıkarılabilecek en doğru sonuç hangisidir?', 'Teknolojik ürünler ihtiyaçlara göre zamanla gelişir.', ['Telefonlar hiç değişmemiştir.', 'Akıllı telefon ilk telefondur.', 'Eski telefonlar bugün de en çok kullanılandır.'])]]),

    'hafta-19': W(19, 4, 'Buluşlar ve Mucitler', 'Buluşların toplum yaşamına etkisi', () => [[
      ortak(p('Bazı mucitler ve buluşları:') + tablo(['Mucit', 'Buluş', 'Çözdüğü sorun'], [['El-Cezerî', 'Otomatik su saati', 'Zamanı ölçmek'], ['Gutenberg', 'Matbaa', 'Kitapları hızlı çoğaltmak'], ['Edison', 'Ampul (geliştirdi)', 'Geceleri aydınlanmak'], ['Aziz Sancar', 'DNA onarımı araştırması', 'Hastalıkları anlamak']]), [
        () => coktan('', 'Matbaanın bulunması toplumda en çok neyi değiştirmiştir?', 'Bilginin daha çok kişiye ulaşmasını', ['Gecelerin aydınlanmasını', 'Zamanın ölçülmesini', 'Yolculukların kısalmasını']),
        () => coktan('', 'Tabloya göre buluşların ortak özelliği nedir?', 'Hepsi bir sorunu çözmek için ortaya çıkmıştır.', ['Hepsi aynı yüzyılda yapılmıştır.', 'Hepsi elektrikle çalışır.', 'Hepsini aynı kişi bulmuştur.'])]),
      kodDY('Öğrenciler mucitlerin özellikleriyle ilgili bilgileri değerlendiriyor.', [
        ['Mucitler meraklı ve sabırlıdır.', true], ['Mucitler ilk denemede başaramazsa vazgeçer.', false], ['Bir buluş başka buluşlara yol açabilir.', true], ['Yalnızca yetişkinler mucit olabilir.', false]], 'u2'),
      yolDY('Kaan, buluşlarla ilgili bir yol oyunu oynuyor.', [['Ampul, ateşin bulunmasından önce icat edilmiştir.', false], ['El-Cezerî otomatik makineler tasarlamıştır.', true], ['Matbaa kitapların çoğalmasını kolaylaştırmıştır.', true]], 'u3')], [
      konusma('Bir mucidin günlüğünden: "İlk denemem başarısız oldu. İkinci denemede kanatlar kırıldı. Üçüncü denemede tasarımı değiştirdim ve sonunda çalıştı!" Öğrenciler bu günlüğü yorumladı.', [
        ['Defne', 'Mucit hatalarından ders çıkarmıştır.', true], ['Arda', 'Mucit şanslı olduğu için başarmıştır.', false],
        ['Elif', 'Mucit sabırlı ve kararlıdır.', true], ['Mert', 'Başarısız denemeler zaman kaybıdır.', false]], 'u4'),
      kapDY('Öğretmen, buluşların yararları ve zararlarıyla ilgili kartları kaplara atıyor.', [
        ['Otomobiller ulaşımı hızlandırmıştır.', true], ['Teknolojik ürünlerin atıkları çevreye zarar verebilir.', true], ['Buluşların hiçbir olumsuz yanı olamaz.', false], ['Telefon, uzaktaki insanları yakınlaştırmıştır.', true]], 'u5'),
      coktan(p('Ela, bitkileri sulamayı sık sık unuttuğunu fark etti. Toprak kuruyunca ışık yakan basit bir uyarı düzeneği tasarladı ve sınıfında sergiledi.'), 'Ela\'nın bu çalışması mucitlerin hangi özelliğini gösterir?', 'Günlük bir soruna çözüm üretmek', ['Başkasının buluşunu kopyalamak', 'Sorunları görmezden gelmek', 'Yalnızca para kazanmak'])]]),

    'hafta-20': W(20, 4, 'Teknolojiyi Güvenli Kullan', 'Teknolojik ürünlerin bilinçli kullanımı', () => [[
      ortak(p('Barış\'ın bir haftalık ekran süresi grafikte verilmiştir.') + grafik('Ekran süresi', ['Pzt', 'Sal', 'Çar', 'Per', 'Cum', 'Cmt', 'Paz'], [2, 1, 3, 2, 2, 5, 6], 'Saat', '#f2546b'), [
        () => coktan('', 'Uzmanlar bu yaştaki çocuklar için günde en çok 2 saat ekran süresi öneriyor. Barış kaç gün bu sınırı aşmıştır?', '3', ['1', '2', '4']),
        () => coktan('', 'Barış\'ın haftalık toplam ekran süresi kaç saattir?', '21', ['19', '20', '23'])]),
      roma(p('Ayşe ıslak elleriyle saç kurutma makinesinin fişini prize takmak istedi. Annesi hemen onu durdurdu ve elektrikli araçları kullanırken dikkat edilmesi gerekenleri anlattı.'), 'Annesinin anlattıklarından hangileri doğru olabilir?', [['Islak elle elektrikli araçlara dokunulmaz.', true], ['Fiş prizden kablosundan çekilerek çıkarılır.', false], ['Kablosu hasarlı araç kullanılmaz.', true]]),
      sirala('Tablet kullanırken uyulması gereken bir "ekran planı" adımları karışık verilmiştir.', ['Ödevlerimi bitiririm.', 'Ailemle ekran süremi belirlerim.', 'Belirlenen süre kadar kullanırım.', 'Gözlerimi dinlendirmek için ara veririm.'], 'Hangi sıralama en uygundur?', 'v3'),
      bulmaca('Teknoloji bulmacası:', [['Harcadığımız elektriğin bedelinin yazdığı kâğıt.', 'FATURA'], ['Bilgisayarları birbirine bağlayan ağ.', 'İNTERNET'], ['Pilin yeniden doldurulması.', 'ŞARJ']], 'v4')], [
      esle('Teknolojik ürünlerin yanlış kullanımı ve olası zararları karışık verilmiştir.', [['Kulaklıkla çok yüksek ses dinlemek', 'İşitme kaybı'], ['Ekrana çok yakından bakmak', 'Göz yorgunluğu'], ['Gece geç saate kadar tablet kullanmak', 'Uyku düzeninin bozulması'], ['Uzun süre eğik oturmak', 'Bel ve boyun ağrısı']], 'Doğru eşleştirme hangisidir?', 'v5'),
      coktan(p('Bir evde kullanılmayan cihazların fişleri hep prizde kalıyor. Aile bir ay boyunca kullanılmayan cihazların fişini çekti ve elektrik faturası azaldı.'), 'Bu durumdan çıkarılabilecek en doğru sonuç hangisidir?', 'Bilinçli kullanım hem bütçeyi hem doğayı korur.', ['Fişleri çekmek cihazları bozar.', 'Elektrik faturası hiç değişmez.', 'Cihazlar hiç kullanılmamalıdır.']),
      coktan(p('Selin her gece yatağında telefonla oyun oynuyor ve sabahları okula yorgun gidiyor.'), 'Selin için en uygun öneri hangisidir?', 'Yatmadan önce ekranı kapatıp telefonu odasının dışında şarj etmek', ['Daha parlak ekranla oynamak', 'Sabah daha geç kalkmak', 'Okulda uyumak'])]]),

    'hafta-21': W(21, 4, 'İnternette Güvendeyim', 'İnternette güvenlik', () => [[
      kacTane(p('Duru\'ya tanımadığı biri şu mesajı gönderdi: "Merhaba! Ben de 10 yaşındayım. Hangi okula gidiyorsun? Ev adresini verir misin, sana hediye göndereceğim."') + p('Duru\'nun arkadaşları şu önerilerde bulundu:'), [
        ['Mesaja cevap vermeyip ailene haber ver.', true], ['Adresini değil, yalnızca okulunun adını yaz.', false], ['Bu kişiyi engelle ve bildir.', true], ['Hediye için fotoğrafını gönder.', false]]),
      tabloSec(p('Bilişim dersinde öğretmen üç şifre yazdı: "123456", "ali2016", "Mavi!Kuş7Uçar".'), 'Şifrelerin güvenlik düzeyi hangi seçenekte doğru verilmiştir?', ['123456', 'ali2016', 'Mavi!Kuş7Uçar'], ['Çok zayıf', 'Zayıf', 'Güçlü'], [['Güçlü', 'Zayıf', 'Çok zayıf'], ['Zayıf', 'Güçlü', 'Çok zayıf'], ['Çok zayıf', 'Güçlü', 'Zayıf']], 'y2'),
      kareYol('Efe, internet güvenliği bilgileriyle kare oyunu oynuyor.', [['İnternette paylaştığımız fotoğraflar başkalarınca kaydedilebilir.', true], ['Şifremizi en yakın arkadaşımıza söylemeliyiz.', false], ['Şüpheli bağlantılara tıklamamalıyız.', true], ['Her internet sitesindeki bilgi doğrudur.', false]], 'y3')], [
      cocukSec(p('Sosyal medyada "Yarın okullar tatil!" diye bir paylaşım görüldü. Paylaşımın kimden geldiği belli değil. Öğrenciler ne yapılması gerektiğini konuşuyor.'), 'Hangi öğrencinin önerisi yanlıştır?', ['Hemen bütün arkadaşlarıma gönderirim.', 'Valiliğin resmî açıklamasına bakarım.', 'Okulun sitesini kontrol ederim.', 'Ailemle birlikte doğruluğunu araştırırım.'], 'y4'),
      ortak(p('İnternette yaptığımız her paylaşım, yazdığımız her yorum ve gezdiğimiz siteler bir iz bırakır. Bu izlere "dijital ayak izi" denir. Silinen paylaşımlar bile başkaları tarafından kaydedilmiş olabilir.'), [
        () => coktan('', 'Metne göre aşağıdakilerden hangisi dijital ayak izi oluşturmaz?', 'Defterine günlük yazmak', ['Bir fotoğrafa yorum yazmak', 'Bir video paylaşmak', 'Bir internet sitesini ziyaret etmek']),
        () => coktan('', 'Metinden çıkarılabilecek en önemli öğüt hangisidir?', 'Paylaşım yapmadan önce iyi düşünmeliyiz.', ['İnternet hiç kullanılmamalıdır.', 'Paylaşımlar her zaman silinebilir.', 'Yorum yazmak zararsızdır.'])]),
      coktan(p('Ali, bir oyunda tanıştığı kişinin kendisini sürekli kötü sözlerle rahatsız ettiğini fark etti.'), 'Ali\'nin yapması gereken en doğru davranış hangisidir?', 'Durumu ailesine anlatıp kişiyi engellemek', ['Ona daha kötü sözlerle cevap vermek', 'Kimseye söylemeden oynamaya devam etmek', 'Şifresini bu kişiyle paylaşmak'])]]),

    'hafta-22': W(22, 4, 'Emeğe Saygı', 'Fikrî ürünlere saygı (telif)', () => [[
      ortak(p('Mert bir internet sitesindeki yazıyı olduğu gibi kopyalayıp kendi ödevi gibi teslim etti. Ece ise aynı sitedeki bilgileri okudu, kendi cümleleriyle yazdı ve kaynağını belirtti.'), [
        () => coktan('', 'Hangi öğrenci başkasının emeğine saygı göstermiştir?', 'Ece', ['Mert', 'İkisi de', 'Hiçbiri']),
        () => coktan('', 'Mert\'in davranışı neden yanlıştır?', 'Başkasının emeğini kendi emeği gibi göstermiştir.', ['Çok uzun yazmıştır.', 'İnternet kullanmıştır.', 'Ödevini erken teslim etmiştir.'])]),
      kodDY('Öğrenciler fikrî haklarla ilgili bilgileri değerlendiriyor.', [
        ['Bir şiirin şairine ait hakları vardır.', true], ['İzinsiz çoğaltılmış kitap almak doğrudur.', false], ['Kaynak göstermek emeğe saygıdır.', true], ['Başkasının çizdiği resmi adımızla yarışmaya gönderebiliriz.', false]], 'z2'),
      yolDY('Su, emeğe saygıyla ilgili yol oyunu oynuyor.', [['Arkadaşımın fikrini kendi fikrim gibi anlatabilirim.', false], ['Korsan ürünler sanatçılara zarar verir.', true], ['Kaynak göstermeden alıntı yapmak doğrudur.', false]], 'z3')], [
      konusma('Bir pazarda sanatçıların izni olmadan çoğaltılmış CD\'ler çok ucuza satılıyor. Öğrenciler bu durumu konuşuyor.', [
        ['Ada', 'Bunları almamalıyız çünkü sanatçının emeğine zarar verir.', true], ['Can', 'Ucuz oldukları için almak akıllıca bir davranıştır.', false],
        ['Efe', 'Korsan ürünler yasalara aykırıdır.', true], ['Bora', 'Sanatçılar şarkılarından kazanç sağlamamalıdır.', false]], 'z4'),
      kapDY('Öğretmen "emeğe saygı" kartlarını kaplara atıyor.', [
        ['Okuduğum kitabın yazarını ödevime yazarım.', true], ['Arkadaşımın ödevini kopyalayıp teslim etmek sorun değildir.', false], ['Sanat eserlerinin sahibinin izni olmadan kullanılmaması gerekir.', true], ['Fotoğraf çeken kişinin de hakları vardır.', true]], 'z5'),
      coktan(p('Okulun resim yarışmasında birinci olan resmin, internetteki bir resmin aynısı olduğu anlaşıldı. Yarışma kurulu ödülü geri aldı.'), 'Kurulun bu kararı en çok hangi değeri korur?', 'Emeğe saygı ve dürüstlük', ['Hız', 'Cömertlik', 'Merak'])]]),

    'hafta-23': W(23, 5, 'İhtiyaç mı, İstek mi?', 'İhtiyaç ve istek', () => [[
      ortak(p('Bir ailenin alışveriş listesi:') + tablo(['Ürün', 'Fiyat'], [['Ekmek', '15 TL'], ['Süt', '40 TL'], ['Oyuncak robot', '450 TL'], ['Okul defteri', '30 TL'], ['Çikolata', '25 TL'], ['Kışlık mont', '900 TL']]), [
        () => coktan('', 'Ekmek, süt ve defter almak için kaç TL gerekir?', '85', ['75', '95', '105']),
        () => coktan('', 'Parası sınırlı olan bu aile önce hangilerini almalıdır?', 'Ekmek, süt, defter ve mont', ['Oyuncak robot ve çikolata', 'Yalnızca çikolata', 'Oyuncak robot ve mont'])]),
      roma(p('Televizyonda "Bu ayakkabıyı giyen herkes en hızlı koşucu olur!" diye bir reklam vardı. Kaan\'ın ayakkabısı yeni olmasına rağmen o da bu ayakkabıyı istedi.'), 'Bu durumla ilgili aşağıdaki yargılardan hangileri doğrudur?', [['Reklamlar istekleri artırabilir.', true], ['Kaan\'ın yeni ayakkabıya ihtiyacı vardır.', false], ['Reklamdaki iddia abartılıdır.', true]]),
      sirala('Bilinçli bir alışveriş yapmak için Elif\'in izlediği adımlar karışık verilmiştir.', ['İhtiyacımı belirlerim.', 'Bütçemi kontrol ederim.', 'Fiyatları karşılaştırırım.', 'Satın alır ve fişimi saklarım.'], 'Adımların doğru sırası hangisidir?', 'aa3'),
      bulmaca('Ekonomi bulmacası:', [['Harcamadan ayırdığımız para.', 'BİRİKİM'], ['Satın alınan mal.', 'ÜRÜN'], ['Mal ve hizmeti satın alıp kullanan kişi.', 'TÜKETİCİ'], ['Alışveriş yapılan dükkânların bulunduğu yer.', 'ÇARŞI'], ['Temel ihtiyacımız olan bir besin.', 'EKMEK']], 'aa4')], [
      esle('Aşağıdaki durumlar ve doğru kararlar karışık verilmiştir.', [['Ayakkabısı küçülen çocuk', 'Yeni ayakkabı almak ihtiyaçtır.'], ['Aynı oyuncaktan bir tane daha isteyen çocuk', 'Bu bir istektir, beklenebilir.'], ['Kalemi bitmiş öğrenci', 'Kalem almak ihtiyaçtır.'], ['Reklamdaki pahalı tişörtü isteyen çocuk', 'Reklamın etkisi düşünülmelidir.']], 'Doğru eşleştirme hangisidir?', 'aa5'),
      coktan(p('Doğum gününde 500 TL harçlık alan Ece\'nin okul çantası yırtık, bir de çok istediği bir oyun var. Çanta 300 TL, oyun 400 TL.'), 'Ece için en bilinçli karar hangisidir?', 'Önce çantayı alıp kalan parayı oyun için biriktirmek', ['Bütün parayı oyuna vermek', 'Arkadaşından borç alıp ikisini de almak', 'Parayı hiç harcamamak']),
      coktan(p('Temel ihtiyaçlar yaşamımızı sürdürmek için gerekli olanlardır.'), 'Aşağıdakilerden hangisi temel ihtiyaçlardan biri değildir?', 'Oyun konsolu', ['Barınma', 'Beslenme', 'Giyinme'])]]),

    'hafta-24': W(24, 5, 'Bütçemi Yapıyorum', 'Bütçe ve birikim', () => [[
      kacTane(p('Selin\'in bir aylık harçlık defteri:') + tablo(['Hafta', 'Gelir', 'Gider', 'Kalan'], [['1. hafta', '200 TL', '150 TL', '50 TL'], ['2. hafta', '200 TL', '120 TL', '80 TL'], ['3. hafta', '200 TL', '200 TL', '0 TL'], ['4. hafta', '200 TL', '90 TL', '110 TL']]) + p('Selin\'in arkadaşları şu yorumları yaptı:'), [
        ['Selin bir ayda 240 TL biriktirmiştir.', true], ['En çok harcamayı 3. haftada yapmıştır.', true], ['Selin\'in her hafta geliri farklıdır.', false], ['Selin\'in bir aylık toplam gideri 560 TL\'dir.', true]]),
      grafikSec(p('Kaan dört hafta boyunca her hafta biriktirdiği parayı yazdı: 1. hafta 40 TL, 2. hafta 60 TL, 3. hafta 20 TL, 4. hafta 80 TL.'), 'Kaan\'ın birikimini gösteren grafik hangisidir?', ['1.', '2.', '3.', '4.'], [40, 60, 20, 80], [[40, 20, 60, 80], [80, 60, 40, 20], [20, 40, 60, 80]], 'ab2', 'TL'),
      kareYol('Defne, bütçe bilgileriyle kare oyunu oynuyor.', [['Bütçe, gelir ve giderlerin planlanmasıdır.', true], ['Gider gelirden fazlaysa birikim artar.', false], ['Birikim yapmak gelecekteki ihtiyaçlar için önemlidir.', true], ['Kalan = Gelir + Gider\'dir.', false]], 'ab3')], [
      tabloSec(p('Bir ailenin aylık geliri 30 bin TL\'dir. Kira 12 bin, mutfak 8 bin, faturalar 4 bin, ulaşım 3 bin TL tutuyor.'), 'Bu ailenin toplam gideri ve aylık birikimi hangi seçenekte doğru verilmiştir?', ['Toplam gider', 'Birikim'], ['27 bin TL', '3 bin TL'], [['24 bin TL', '6 bin TL'], ['27 bin TL', '7 bin TL'], ['30 bin TL', '0 TL']], 'ab4'),
      cocukSec(p('Selin 600 TL\'lik bir kaykay almak istiyor ve her hafta 100 TL biriktirmeye karar verdi. Arkadaşları Selin\'in planını yorumladı.'), 'Hangi öğrencinin söylediği yanlıştır?', ['Selin kaykayı 4 haftada alabilir.', 'Selin hedefine 6 haftada ulaşır.', 'Haftalık birikimini artırırsa daha erken alabilir.', 'Plan yapmak hedefe ulaşmayı kolaylaştırır.'], 'ab5'),
      coktan(p('Bir ailenin elektrik faturası kışın çok yüksek geldi. Aile, odadan çıkarken ışıkları söndürmeye, kullanılmayan cihazların fişini çekmeye ve LED ampul kullanmaya karar verdi.'), 'Ailenin bu kararlarının bütçeye etkisi ne olur?', 'Giderleri azalır, birikimleri artar.', ['Gelirleri azalır.', 'Giderleri artar.', 'Bütçeleri hiç değişmez.'])]]),

    'hafta-25': W(25, 5, 'Bilinçli Tüketici', 'Bilinçli tüketicilik', () => [[
      ortak(p('Ali\'nin aldığı yoğurdun etiketi:') + etiket([['Ürün', 'Meyveli yoğurt'], ['Üretim tarihi', '02.03.2027'], ['Son tüketim tarihi', '16.03.2027'], ['Saklama', '+4 °C\'de buzdolabında'], ['Belge', 'TSE ✓'], ['Fiyat', '35 TL']]), [
        () => coktan('', 'Ürün üretildikten kaç gün sonra son tüketim tarihi dolar?', '14', ['10', '12', '16']),
        () => coktan('', 'Ali yoğurdu 20.03.2027\'de buzdolabında buldu. Ne yapmalıdır?', 'Son tüketim tarihi geçtiği için yememelidir.', ['Hemen yemelidir.', 'Isıtıp yemelidir.', 'Arkadaşına vermelidir.'])]),
      kodDY('Öğrenciler bilinçli tüketicilikle ilgili kartları değerlendiriyor.', [
        ['Alışverişte fiş almak hakkımızı korur.', true], ['Büyük paket her zaman daha ucuzdur.', false], ['Etiketteki saklama koşuluna uymalıyız.', true], ['TSE işareti ürünün en pahalı olduğunu gösterir.', false]], 'ac2'),
      yolDY('Ece, alışveriş bilgileriyle yol oyunu oynuyor.', [['Reklamdaki her bilgi doğrudur.', false], ['Bozuk ürün fişle değiştirilebilir.', true], ['Alışverişten önce ihtiyaç listesi yapılmalıdır.', true]], 'ac3')], [
      konusma('Üç marketteki pirinç fiyatları: A Market 1 kg 80 TL, B Market 2 kg 150 TL, C Market 5 kg 400 TL. Öğrenciler fiyatları karşılaştırıyor.', [
        ['Can', 'Kilogram fiyatı en ucuz olan B Market\'tir.', true], ['Su', 'En büyük paket en ucuzudur.', false],
        ['Ada', 'A ve C marketlerde kilogram fiyatı aynıdır.', true], ['Efe', 'C Market\'te 1 kilogram pirinç 75 TL\'dir.', false]], 'ac4'),
      kapDY('Tüketici hakları haftasında öğrencilerin hazırladığı kartlar kaplara atılıyor.', [
        ['Satın aldığımız bozuk ürün için başvuru yapabiliriz.', true], ['Son kullanma tarihi geçmiş ürünler satılabilir.', false], ['Ürün etiketleri bizi bilgilendirir.', true], ['Fişi hemen atmak en doğru davranıştır.', false]], 'ac5', 'doğru'),
      coktan(p('Ali yeni aldığı oyuncağın iki gün sonra bozulduğunu fark etti. Fişini saklamıştı.'), 'Ali\'nin yapması gereken en doğru davranış hangisidir?', 'Fişiyle mağazaya başvurup değişim istemek', ['Oyuncağı atmak', 'Arkadaşına satmak', 'Kendisi sökmeye çalışmak'])]]),

    'hafta-26': W(26, 5, 'Yöremin Ürünleri', 'Yaşadığı yerin ekonomik faaliyetleri', () => [[
      ortak(p('Bazı illerimiz ve öne çıkan ürünleri:') + tablo(['İl', 'Ürün', 'Faaliyet'], [['Rize', 'Çay', 'Tarım'], ['Gaziantep', 'Fıstık, baklava', 'Tarım, sanayi'], ['Bursa', 'Otomobil, ipek', 'Sanayi'], ['Antalya', 'Turizm, portakal', 'Turizm, tarım'], ['Zonguldak', 'Kömür', 'Madencilik']]), [
        () => coktan('', 'Rize\'de çay yetişmesinin en önemli nedeni hangisidir?', 'Bol yağış ve uygun iklim', ['Kömür madenleri', 'Fabrikaların çok olması', 'Turistlerin gelmesi']),
        () => coktan('', 'Tabloya göre hangi ilde sanayi ve tarım birlikte öne çıkar?', 'Gaziantep', ['Rize', 'Zonguldak', 'Antalya'])]),
      roma(p('Malatya kayısısı, Aydın inciri ve Kayseri pastırması "coğrafi işaretli" ürünlerdir. Coğrafi işaret, ürünün o yöreye özgü olduğunu gösterir.'), 'Coğrafi işaretle ilgili aşağıdakilerden hangileri doğrudur?', [['Ürünün tanınmasını sağlar.', true], ['Üreticinin emeğini korur.', true], ['Ürünün her yerde üretilebileceğini gösterir.', false]]),
      sirala('Rize\'de çayın yolculuğu karışık verilmiştir.', ['Çay bahçelerinde yapraklar toplanır.', 'Yapraklar fabrikaya taşınır.', 'Fabrikada kurutulup paketlenir.', 'Paketler marketlere dağıtılır.'], 'Doğru sıralama hangisidir?', 'ad3'),
      bulmaca('Yöremin ürünleri bulmacası:', [['Sanayi ürünlerinin üretildiği yer.', 'FABRİKA'], ['Büyük akarsu.', 'IRMAK'], ['Sonbaharda yetişen kırmızı taneli meyve.', 'NAR'], ['Balıkçılık yapılan geniş su.', 'DENİZ'], ['Sıcak su kaynağı.', 'ILICA'], ['Zonguldak\'tan çıkarılan yakıt.', 'KÖMÜR']], 'ad4')], [
      esle('Bazı yörelerin özellikleri ve ekonomik faaliyetleri karışık verilmiştir.', [['Geniş ve verimli ovaları olan yöre', 'Tarım'], ['Denize kıyısı ve tarihî yerleri çok olan yöre', 'Turizm'], ['Yer altında kömür yatakları olan yöre', 'Madencilik'], ['Fabrikaları ve limanları olan yöre', 'Sanayi']], 'Doğru eşleştirme hangisidir?', 'ad5'),
      coktan(p('Kerem\'in yaşadığı ilçede halkın çoğu seralarda domates ve biber yetiştiriyor. İlçede ürünleri paketleyen tesisler ve ürünleri taşıyan nakliye firmaları da var.'), 'Bu ilçede seracılığın gelişmesi hangi meslekleri de etkilemiştir?', 'Paketleme işçisi ve kamyon şoförü', ['Pilot ve astronot', 'Madenci ve balıkçı', 'Kaptan ve dalgıç']),
      coktan(p('Bir ilçe, yöresel ürünü olan bal için her yıl festival düzenliyor. Festivale binlerce kişi geliyor.'), 'Festivalin ilçeye en önemli katkısı hangisidir?', 'Ürünün tanınması ve ilçe ekonomisinin canlanması', ['Arıların azalması', 'Balın ucuzlaması', 'Yolların kapanması'])]]),

    'hafta-27': W(27, 5, 'Tarladan Sofraya', 'Üretim, dağıtım ve tüketim; meslekler', () => [[
      kacTane(p('Ekmeğin yolculuğu:') + serit([['1', 'Çiftçi buğday eker'], ['2', 'Biçerdöver hasat eder'], ['3', 'Değirmende un olur'], ['4', 'Kamyonla taşınır'], ['5', 'Fırında pişer'], ['6', 'Markette satılır']]) + p('Öğrenciler bu süreçle ilgili şu yorumları yaptı:'), [
        ['Kamyonla taşınması dağıtım aşamasıdır.', true], ['Bu süreçte pilotun da emeği vardır.', false], ['Ekmeği yememiz tüketim aşamasıdır.', true], ['Şoförler çalışmazsa ekmek markete ulaşmaz.', true]]),
      tabloSec(p('Bir ürünün sofraya gelmesi üretim, dağıtım ve tüketim aşamalarından geçer.'), 'Aşağıdaki işler hangi aşamaya aittir?', ['Süt sağmak', 'Sütü markete taşımak', 'Kahvaltıda süt içmek'], ['Üretim', 'Dağıtım', 'Tüketim'], [['Dağıtım', 'Üretim', 'Tüketim'], ['Üretim', 'Tüketim', 'Dağıtım'], ['Tüketim', 'Dağıtım', 'Üretim']], 'ae2'),
      kareYol('Bora, meslekler ve üretimle ilgili kare oyunu oynuyor.', [['Her meslek toplumun bir ihtiyacını karşılar.', true], ['Ekmek israfı kimseye zarar vermez.', false], ['Bir ürünün üretiminde birçok meslek emek verir.', true], ['Dağıtım, ürünü tüketiciye ulaştırmaktır.', true]], 'ae3')], [
      cocukSec(p('Her gün milyonlarca ekmek israf ediliyor. Öğrenciler israfı önlemek için öneride bulundu.'), 'Hangi öğrencinin önerisi israfı artırır?', ['Her öğün taze ekmek alıp bayatı atalım.', 'İhtiyaç kadar ekmek alalım.', 'Bayat ekmekten yemek yapalım.', 'Ekmeği bozulmayacak şekilde saklayalım.'], 'ae4'),
      ortak(p('Bir tekstil fabrikasında tişört üretiliyor: Pamuk tarladan toplanıyor, iplik yapılıyor, kumaş dokunuyor, terziler dikiyor, tişörtler mağazalara gönderiliyor.'), [
        () => coktan('', 'Bu süreçte "dağıtım" aşamasında çalışan kişi hangisidir?', 'Tişörtleri mağazaya taşıyan şoför', ['Pamuk toplayan çiftçi', 'Kumaşı dokuyan işçi', 'Tişörtü diken terzi']),
        () => coktan('', 'Pamuk hasadı kuraklık nedeniyle azalırsa hangisi olması beklenir?', 'Tişört üretimi azalır, fiyatı artabilir.', ['Daha çok tişört üretilir.', 'Mağazalar kapanmaz, hiçbir şey değişmez.', 'Tişörtler ucuzlar.'])]),
      coktan(p('Okul kantininde haftanın en çok satılan ürünü tost oldu. Kantin sahibi her sabah ekmeği fırından, peyniri mandıradan alıyor.'), 'Bu bilgiye göre kantin sahibinin işi hangi aşamalarla bağlantılıdır?', 'Dağıtım ve tüketim', ['Yalnız üretim', 'Yalnız tüketim', 'Hiçbir aşamayla'])]]),

    'hafta-28': W(28, 6, '23 Nisan ve Haklarım', 'Ulusal egemenlik ve çocuk hakları', () => [[
      ortak(p('Çocuk Hakları Sözleşmesi\'nden bazı maddeler:') + tablo(['Madde', 'Hak'], [['12', 'Çocuk görüşünü özgürce ifade eder.'], ['24', 'Her çocuk sağlık hizmetlerinden yararlanır.'], ['28', 'Her çocuk eğitim hakkına sahiptir.'], ['31', 'Her çocuk dinlenme ve oyun hakkına sahiptir.']]), [
        () => coktan('', 'Ders programına teneffüs konulması hangi maddeyle ilgilidir?', '31', ['12', '24', '28']),
        () => coktan('', 'Okula gidemeyip çalıştırılan bir çocuğun hangi hakkı ihlal edilmiştir?', 'Eğitim hakkı', ['Oy kullanma hakkı', 'Ehliyet alma hakkı', 'Seçilme hakkı'])]),
      kodDY('Öğrenciler 23 Nisan ile ilgili kartları değerlendiriyor.', [
        ['TBMM 23 Nisan 1920\'de açıldı.', true], ['23 Nisan yalnızca Türk çocuklarına armağan edilmiştir.', false], ['Atatürk bu bayramı çocuklara armağan etti.', true], ['23 Nisan, Cumhuriyet\'in ilan edildiği gündür.', false]], 'af2'),
      yolDY('Ada, çocuk haklarıyla ilgili yol oyunu oynuyor.', [['Çocuk hakları bütün dünya çocukları içindir.', true], ['Çocukların görüşleri dinlenmelidir.', true], ['Çocuk hakları yalnızca bazı ülkelerde geçerlidir.', false]], 'af3')], [
      konusma('23 Nisan şenliklerine başka ülkelerden çocuklar da katılıyor. Öğrenciler bu konuda konuşuyor.', [
        ['Efe', 'Bu şenlikler dünya çocuklarının dostluğunu güçlendirir.', true], ['Su', '23 Nisan yalnızca okullarda kutlanan bir derstir.', false],
        ['Kaan', 'Farklı ülkelerden çocuklar kültürlerini tanıtır.', true], ['Ece', 'Başka ülkelerden çocukların gelmesi bayramın anlamına aykırıdır.', false]], 'af4'),
      kapDY('Öğretmen hak ve sorumluluk kartlarını kaplara atıyor.', [
        ['Eğitim hakkımızı iyi kullanmak için derslere hazırlıklı gelmeliyiz.', true], ['Haklarımız yalnızca bizimdir, başkalarının hakkı önemsizdir.', false], ['Her hakkın bir sorumluluğu vardır.', true], ['Oyun hakkı yalnızca hafta sonları geçerlidir.', false]], 'af5'),
      coktan(p('Dünyanın bir bölgesinde savaş nedeniyle çocuklar okula gidemiyor. Okulumuz bu çocuklar için kırtasiye yardımı topladı.'), 'Okulun bu davranışı en çok hangisini gösterir?', 'Çocuk haklarının bütün dünya çocukları için önemli olduğunu', ['Kırtasiyenin çok ucuz olduğunu', 'Okulun tatil olduğunu', 'Savaşın çocukları etkilemediğini'])]]),

    'hafta-29': W(29, 6, 'Haklarım ve Sorumluluklarım', 'Haklar ve sorumluluklar', () => [[
      ortak(p('Mahalle parkındaki salıncakların sırası çok uzundu. Ege 20 dakikadır salıncakta sallanıyor ve inmek istemiyor. Sırada küçük çocuklar bekliyor.'), [
        () => coktan('', 'Ege\'nin davranışı için hangisi söylenebilir?', 'Hakkını kullanırken başkalarının hakkını engellemiştir.', ['Sorumluluğunu yerine getirmiştir.', 'Küçüklere yardım etmiştir.', 'Park kurallarına uymuştur.']),
        () => coktan('', 'Bu sorunu çözmek için en uygun öneri hangisidir?', 'Herkese eşit süre veren bir sıra kuralı koymak', ['Salıncakları sökmek', 'Yalnız büyüklerin binmesine izin vermek', 'Parkı kapatmak'])]),
      roma(p('Okul servisinde şu kurallar asılıdır: Emniyet kemeri takılır. Serviste ayağa kalkılmaz. Yüksek sesle bağırılmaz.'), 'Bu kurallara uymak aşağıdakilerden hangilerini korur?', [['Kendi güvenliğimizi', true], ['Şoförün dikkatini ve diğer yolcuların güvenliğini', true], ['Servisin daha hızlı gitmesini', false]]),
      sirala('Elif, okulda bozulan bir musluğu fark etti ve sorunu çözmek için şunları yaptı (karışık verilmiştir).', ['Musluğun su kaçırdığını gördü.', 'Durumu sınıf öğretmenine bildirdi.', 'Öğretmen okul müdürüne iletti.', 'Görevli musluğu tamir etti.'], 'Olayların doğru sırası hangisidir?', 'ag3'),
      bulmaca('Sorumluluk bulmacası:', [['Okulda bize ders anlatan kişi.', 'ÖĞRETMEN'], ['Halkın ortak işlerini yürüten büyük kurum: … ve millet.', 'DEVLET'], ['Okula gitme hakkımızla ilgili sözcük.', 'EĞİTİM'], ['Okul ve yolların yapımında kullanılan, vatandaşların ödediği para.', 'VERGİ']], 'ag4')], [
      esle('Bazı haklar ve bu haklarla ilgili sorumluluklar karışık verilmiştir.', [['Eğitim hakkı', 'Derslere hazırlıklı gelmek'], ['Sağlık hakkı', 'Dengeli beslenip spor yapmak'], ['Oyun hakkı', 'Ortak alanları paylaşmak'], ['Temiz çevrede yaşama hakkı', 'Çöpleri çöp kutusuna atmak']], 'Doğru eşleştirme hangisidir?', 'ag5'),
      coktan(p('Kamu malları, devletin vatandaşların vergileriyle yaptığı ve herkesin ortak kullandığı yerler ve eşyalardır.'), 'Aşağıdakilerden hangisi bir kamu malı değildir?', 'Ailemizin arabası', ['Okul sırası', 'Park bankı', 'Otobüs durağı']),
      coktan(p('Mahallede bazı çocuklar parktaki oyuncakların üzerine yazı yazıyor.'), 'Bu durumu gören bir çocuğun yapabileceği en uygun davranış hangisidir?', 'Arkadaşlarını uyarıp durumu büyüklerine bildirmek', ['Onlara katılmak', 'Görmezden gelmek', 'Oyuncakları kırmak'])]]),

    'hafta-30': W(30, 6, 'Katılıyorum, Seçiyorum', 'Demokratik katılım ve seçim', () => [[
      kacTane(p('4-B sınıf başkanlığı seçim sonuçları grafikte verilmiştir.') + grafik('Seçim sonuçları', ['Ayşe', 'Burak', 'Cemre', 'Doruk'], [9, 7, 11, 3], 'Oy', '#f4a100') + p('Öğrenciler sonuçları yorumladı:'), [
        ['Seçimi Cemre kazanmıştır.', true], ['Sınıfta 30 öğrenci oy kullanmıştır.', true], ['Ayşe ile Burak\'ın oyları toplamı Cemre\'nin oyundan azdır.', false], ['Doruk en az oyu almıştır.', true]]),
      grafikSec(p('5-A sınıfında yapılan seçimde Ece 6, Mert 10, Lale 8, Can 4 oy aldı.'), 'Bu seçimin sonuçlarını gösteren grafik hangisidir?', ['Ece', 'Mert', 'Lale', 'Can'], [6, 10, 8, 4], [[10, 6, 8, 4], [6, 8, 10, 4], [4, 10, 8, 6]], 'ah2', 'Oy'),
      kareYol('Kerem, seçimle ilgili bilgileri değerlendiriyor.', [['Seçimlerde gizli oy kullanılır.', true], ['Seçimi en az oy alan kazanır.', false], ['Seçim sonuçlarına saygı göstermeliyiz.', true], ['Her vatandaş istediği kadar oy kullanabilir.', false], ['Oylar açık olarak sayılır.', true]], 'ah3')], [
      tabloSec(p('Ayşe ve Doruk\'un seçim vaatleri: Ayşe "Sınıf kütüphanesi kuracağız." Doruk "Hiç ödev verilmeyecek!" dedi.'), 'Vaatlerin gerçekleştirilebilirliği hangi seçenekte doğru değerlendirilmiştir?', ['Ayşe', 'Doruk'], ['Gerçekleştirilebilir', 'Gerçekleştirilemez'], [['Gerçekleştirilemez', 'Gerçekleştirilebilir'], ['Gerçekleştirilebilir', 'Gerçekleştirilebilir'], ['Gerçekleştirilemez', 'Gerçekleştirilemez']], 'ah4'),
      cocukSec(p('Mahalledeki parkın aydınlatması bozuk olduğu için çocuklar akşamları parkta oynayamıyor. Öğrenciler ne yapılabileceğini konuşuyor.'), 'Hangi öğrencinin önerisi yanlıştır?', ['Lambaları kendimiz tamir etmeye çalışalım.', 'Muhtarlığa durumu bildirelim.', 'Belediyeye dilekçe yazalım.', 'Ailemizden yardım isteyelim.'], 'ah5'),
      coktan(p('Okul meclisi, okulun bahçesine bank konmasını öğrencilerin oylarıyla karara bağladı ve müdüre iletti.'), 'Bu durum öğrencilerin hangi hakkını kullandığını gösterir?', 'Karar alma süreçlerine katılma hakkı', ['Oy kullanma yaşının dolması', 'Bahçe sahibi olma hakkı', 'Ders seçme hakkı'])]]),

    'hafta-31': W(31, 6, 'Kurumlar Bize Hizmet Eder', 'Kamu kurumları ve hizmetleri', () => [[
      ortak(p('Bir mahallede yaşanan sorunlar:') + tablo(['No', 'Sorun'], [['1', 'Evin önündeki çöpler toplanmadı.'], ['2', 'Kardeş hastalandı.'], ['3', 'Kimlik kartının süresi doldu.'], ['4', 'Ormanda yangın çıktı.']]), [
        () => coktan('', '1 ve 3 numaralı sorunlar için hangi kurumlara başvurulmalıdır?', 'Belediye - Nüfus Müdürlüğü', ['Hastane - Belediye', 'Okul - Postane', 'Nüfus Müdürlüğü - Hastane']),
        () => coktan('', '4 numaralı durumda hangi numara aranmalıdır?', '112', ['155 (yalnızca polis)', '186', '444'])]),
      kodDY('Öğrenciler kamu kurumlarıyla ilgili bilgileri değerlendiriyor.', [
        ['Belediyeler park ve yol yapar.', true], ['Muhtarlar okul müdürlerini seçer.', false], ['Kızılay kan bağışı toplar.', true], ['Hastaneler kimlik kartı verir.', false]], 'ai2'),
      yolDY('Su, kurumlarla ilgili yol oyunu oynuyor.', [['AFAD afetlerde yardım eder.', true], ['Kamu kurumları vergilerle hizmet verir.', true], ['Belediye kitaplarımızı yazar.', false]], 'ai3')], [
      konusma('Okulların, yolların ve hastanelerin yapımında vatandaşların ödediği vergiler kullanılır. Öğrenciler bu bilgiyi yorumladı.', [
        ['Mert', 'Okul eşyalarını korumak hepimizin görevidir.', true], ['Ada', 'Okul sıralarına zarar vermek kimseyi etkilemez.', false],
        ['Elif', 'Kamu malları hepimizin ortak malıdır.', true], ['Can', 'Vergi yalnızca okullar için kullanılır.', false]], 'ai4'),
      kapDY('Öğretmen kurumlar ve hizmetleriyle ilgili kartları kaplara atıyor.', [
        ['Postane mektup ve kargo hizmeti verir.', true], ['Muhtarlık mahallenin sorunlarını ilgililere iletir.', true], ['İtfaiye yalnızca yangınlarda çalışır, kurtarma yapmaz.', false], ['Nüfus müdürlüğü kimlik kartı verir.', true]], 'ai5'),
      coktan(p('Kerem\'in dedesi emekli olduktan sonra her hafta Kızılay\'a kan bağışlamaya ve AFAD gönüllüsü olarak eğitimlere katılmaya başladı.'), 'Dedenin davranışları en çok hangisine örnektir?', 'Topluma gönüllü katkı sağlamaya', ['Vergi ödemeye', 'Seçimlerde oy kullanmaya', 'Alışveriş yapmaya'])]]),

    'hafta-32': W(32, 6, 'Millî Sembollerimiz', 'Millî semboller ve 19 Mayıs', () => [[
      ortak(p('Türk bayrağı kırmızı zemin üzerinde beyaz ay ve yıldızdan oluşur. Ölçüleri 1936\'da çıkarılan Türk Bayrağı Kanunu ile belirlenmiştir. Bayrak yere atılmaz; yırtık ya da solmuş bayrak asılmaz.'), [
        () => coktan('', 'Metne göre hangisi yanlış bir davranıştır?', 'Solmuş bir bayrağı asmak', ['Bayrağı millî bayramlarda asmak', 'Bayrağa saygı göstermek', 'Yırtık bayrağı yenisiyle değiştirmek']),
        () => coktan('', 'Bayrağın ölçülerinin kanunla belirlenmesinin nedeni nedir?', 'Her yerde aynı ve doğru şekilde kullanılması', ['Bayrağın pahalı olması', 'Renklerin değişmesi', 'Bayrağın küçük olması'])]),
      roma(p('Millî semboller milletimizin birliğini ve bağımsızlığını temsil eder.'), 'Aşağıdakilerden hangileri millî sembollerimizdendir?', [['İstiklal Marşı', true], ['Türk bayrağı', true], ['Okul formamız', false]]),
      sirala('19 Mayıs ile ilgili olaylar karışık verilmiştir.', ['Atatürk Samsun\'a çıktı.', 'TBMM açıldı.', 'Cumhuriyet ilan edildi.', 'Atatürk 19 Mayıs\'ı gençliğe armağan etti.'], 'Olayların doğru sırası hangisidir?', 'aj3'),
      bulmaca('Millî sembollerimiz bulmacası:', [['Bir milletin başka bir devlete bağlı olmaması.', 'BAĞIMSIZLIK'], ['Başkentimiz.', 'ANKARA'], ['Bayrağımızdaki ayın yanındaki şekil.', 'YILDIZ'], ['Türkçe devletin … dilidir.', 'RESMÎ'], ['Cumhuriyetimizin kurucusu.', 'ATATÜRK'], ['Bayrağımızın zemin rengi.', 'KIRMIZI']], 'aj4')], [
      esle('Millî sembollerimiz ve onlarla ilgili bilgiler karışık verilmiştir.', [['İstiklal Marşı', 'Şairi Mehmet Âkif Ersoy\'dur.'], ['Türk bayrağı', 'Ölçüleri kanunla belirlenmiştir.'], ['Türkçe', 'Resmî dilimizdir.'], ['Ankara', 'Başkentimizdir.']], 'Doğru eşleştirme hangisidir?', 'aj5'),
      coktan(p('Okulda İstiklal Marşı okunurken bazı öğrenciler konuşmaya devam etti.'), 'Bu öğrencilerin davranışı için hangisi söylenebilir?', 'Millî sembollere gereken saygıyı göstermemişlerdir.', ['Doğru bir davranış yapmışlardır.', 'Marşı daha güzel söylemişlerdir.', 'Arkadaşlarına yardım etmişlerdir.']),
      coktan(p('19 Mayıs\'ta okullarda spor gösterileri ve gençlik etkinlikleri yapılır.'), 'Bunun nedeni hangisidir?', 'Atatürk\'ün bu günü gençliğe armağan etmesi', ['Yaz tatilinin başlaması', 'Karne günü olması', 'Yeni yılın başlaması'])]]),

    'hafta-33': W(33, 7, 'Dünyada Farklı Kültürler', 'Farklı kültürler', () => [[
      kacTane(p('Bazı ülkelerde selamlaşma biçimleri:') + tablo(['Ülke', 'Selamlaşma'], [['Türkiye', 'El sıkışma, büyüklerin elini öpme'], ['Japonya', 'Eğilerek selam verme'], ['Yeni Zelanda (Maori)', 'Burun ve alın değdirme'], ['Hindistan', 'Elleri birleştirip "Namaste" deme']]) + p('Öğrenciler tabloyu yorumladı:'), [
        ['Selamlaşma biçimleri kültürden kültüre değişir.', true], ['Japonya\'da selam vermek için eğilinir.', true], ['Bütün ülkelerde aynı şekilde selamlaşılır.', false], ['Farklı selamlaşma biçimlerine saygı göstermeliyiz.', true]]),
      tabloSec(p('Ece üç ülkenin geleneksel yemeklerini araştırdı: İtalya\'da pizza, Japonya\'da suşi, Meksika\'da tako.'), 'Ece\'nin araştırması hangi seçenekte doğru gösterilmiştir?', ['İtalya', 'Japonya', 'Meksika'], ['Pizza', 'Suşi', 'Tako'], [['Suşi', 'Pizza', 'Tako'], ['Pizza', 'Tako', 'Suşi'], ['Tako', 'Suşi', 'Pizza']], 'ak2'),
      kareYol('Lale, farklı kültürlerle ilgili kare oyunu oynuyor.', [['Kültürler farklı olsa da ortak değerler vardır.', true], ['Farklı kültürlerden insanlarla arkadaş olunmaz.', false], ['Misafirperverlik birçok kültürde vardır.', true], ['Başka kültürleri tanımak ön yargıları azaltır.', true]], 'ak3')], [
      cocukSec(p('Dünyanın birçok yerinde misafire yiyecek ikram etmek bir gelenektir: Türkiye\'de çay, İngiltere\'de çay ve kurabiye, Fas\'ta naneli çay.') + p('Öğrenciler bu bilgiyi yorumladı.'), 'Hangi öğrencinin yorumu yanlıştır?', ['Misafire ikram yalnızca Türkiye\'de vardır.', 'Misafirperverlik ortak bir değerdir.', 'İkram edilen yiyecekler kültüre göre değişir.', 'Farklı kültürlerin benzer yanları vardır.'], 'ak4'),
      ortak(p('Okula Japonya\'dan bir öğrenci grubu geldi. Japon öğrenciler eğilerek selam verdi, ayakkabılarını kapıda çıkardı ve öğretmenlerine "sensei" diye seslendi. Türk öğrenciler de onlara çay ikram etti ve halk oyunu gösterdi.'), [
        () => coktan('', 'Bu ziyarette iki kültür arasında hangisi gerçekleşmiştir?', 'Kültürlerin birbirini tanıması', ['Ticaret anlaşması', 'Seçim yapılması', 'Bir yarışma']),
        () => coktan('', 'Japon öğrencilerin selamlaşma biçimine en uygun karşılık hangisidir?', 'Onların selamına saygı gösterip gülümsemek', ['Selamlarına gülmek', 'Onları görmezden gelmek', 'Kendi selamımızı zorla öğretmek'])]),
      coktan(p('Dünyada 7 binden fazla dil konuşulmaktadır. Bazı ülkelerde birden çok resmî dil vardır.'), 'Bu bilgiden çıkarılabilecek en doğru sonuç hangisidir?', 'Dünyada kültürel çeşitlilik çok fazladır.', ['Bütün insanlar aynı dili konuşur.', 'Her ülkenin tek dili vardır.', 'Dil öğrenmek gereksizdir.'])]]),

    'hafta-34': W(34, 7, 'Ülkeler Arası Bağlar', 'Ülkemizin diğer ülkelerle ilişkileri', () => [[
      ortak(p('Bir şirketin yıllık fındık satışı:') + grafik('Fındık satışı (ton)', ['Almanya', 'İtalya', 'Fransa', 'Rusya'], [40, 70, 20, 30], 'Ton', '#8e5b2b'), [
        () => coktan('', 'Şirket toplam kaç ton fındık satmıştır?', '160', ['140', '150', '170']),
        () => coktan('', 'Başka ülkelere ürün satmaya ne ad verilir?', 'İhracat', ['İthalat', 'Tüketim', 'Üretim'])]),
      kodDY('Öğrenciler ülkeler arası ilişkilerle ilgili kartları değerlendiriyor.', [
        ['Turizm ülkeler arasında dostluğu artırır.', true], ['Başka ülkeden ürün almak ihracattır.', false], ['Afetlerde ülkeler birbirine yardım edebilir.', true], ['Ülkeler hiçbir konuda iş birliği yapmaz.', false]], 'al2'),
      yolDY('Mert, ticaret ve turizmle ilgili yol oyunu oynuyor.', [['Turistlerin gelmesi yöre ekonomisine katkı sağlamaz.', false], ['Türkiye fındık ihraç eden ülkelerdendir.', true], ['Ticaret yalnızca komşu ülkelerle yapılır.', false]], 'al3')], [
      konusma('Her yıl milyonlarca turist Kapadokya, Efes ve Pamukkale\'yi ziyaret ediyor. Öğrenciler turizmin etkilerini konuşuyor.', [
        ['Efe', 'Turizm yöre halkına yeni iş alanları sağlar.', true], ['Su', 'Turistler yöresel ürünleri hiç almaz.', false],
        ['Ada', 'Tarihî yerlerin korunması turizmi destekler.', true], ['Bora', 'Turizm ülkemizi dünyaya tanıtır.', true]], 'al4'),
      kapDY('Öğretmen "Türkiye ve dünya" kartlarını kaplara atıyor.', [
        ['Türkiye başka ülkelere arama-kurtarma ekipleri göndermiştir.', true], ['Türkiye\'deki depremlerde başka ülkeler de yardıma gelmiştir.', true], ['Türk dizileri ve yemekleri başka ülkelerde de tanınır.', true], ['Türkiye başka ülkelerden hiç ürün almaz.', false]], 'al5', 'doğru'),
      coktan(p('Evdeki ürünlerin etiketlerine bakan Ece; telefonun Çin\'de, muzun Ekvador\'da, çikolatanın kakaosunun Fildişi Sahili\'nde, çayın ise Rize\'de üretildiğini gördü.'), 'Ece\'nin gözlemi en çok neyi gösterir?', 'Ülkelerin ticaretle birbirine bağlı olduğunu', ['Bütün ürünlerin Türkiye\'de üretildiğini', 'Ticaretin gereksiz olduğunu', 'Ürünlerin hiç taşınmadığını'])]]),

    'hafta-35': W(35, 7, 'Dünyaya Açılan Kapılar', 'Küresel bağlantılar ve iş birliği', () => [[
      ortak(p('Denizlerdeki plastik atıklar akıntılarla bir ülkeden ötekine taşınıyor. Bir ülkenin attığı çöp başka bir ülkenin kıyısına vurabiliyor.'), [
        () => coktan('', 'Bu bilgiden çıkarılabilecek en doğru sonuç hangisidir?', 'Çevre sorunlarının çözümü için ülkeler iş birliği yapmalıdır.', ['Çevre sorunları yalnız bir ülkeyi ilgilendirir.', 'Plastik denizde kaybolur.', 'Akıntılar çöpü temizler.']),
        () => coktan('', 'Bu soruna senin yapabileceğin katkı hangisidir?', 'Plastik kullanımını azaltmak ve atıkları ayırmak', ['Kıyıya çöp atmak', 'Daha çok pet şişe almak', 'Hiçbir şey yapmamak'])]),
      roma(p('Okulumuz başka bir ülkedeki bir okulla "kardeş okul" oldu. Öğrenciler birbirine mektup yazıyor, çevrim içi derslerde buluşuyor.'), 'Bu projenin öğrencilere katkıları hangileridir?', [['Farklı kültürleri tanımak', true], ['Yeni arkadaşlıklar kurmak', true], ['Ders saatlerinin azalması', false]]),
      sirala('Bir ülkede deprem olduktan sonra Türkiye\'nin yaptıkları karışık verilmiştir.', ['Depremin haberi alınır.', 'Arama-kurtarma ekibi hazırlanır.', 'Ekip uçakla bölgeye gider.', 'Enkazdan insanlar kurtarılır.'], 'Doğru sıralama hangisidir?', 'am3'),
      bulmaca('Küresel bağlantılar bulmacası:', [['İnsanlar arasındaki sevgi ve iyi ilişki.', 'DOSTLUK'], ['Sınırları olan, bağımsız devletin toprağı.', 'ÜLKE'], ['Hindistan\'da kullanılan selamlaşma sözcüğü.', 'NAMASTE'], ['Zor durumdakilere destek olmak.', 'YARDIM'], ['Afetlerde yurt içi ve yurt dışında görev yapan kurumumuz.', 'AFAD']], 'am4')], [
      esle('Küresel sorunlar ve çözüm önerileri karışık verilmiştir.', [['Deniz kirliliği', 'Plastik kullanımını azaltmak'], ['Küresel ısınma', 'Enerjiyi tasarruflu kullanmak'], ['Salgın hastalıklar', 'Aşı ve hijyen kurallarına uymak'], ['Orman yangınları', 'Doğada ateş yakmamak']], 'Doğru eşleştirme hangisidir?', 'am5'),
      coktan(p('Dünya Çevre Günü\'nde farklı ülkelerden çocuklar aynı gün kendi şehirlerinde ağaç dikti ve fotoğraflarını ortak bir sitede paylaştı.'), 'Bu etkinlik en çok neyi gösterir?', 'Çocukların ortak bir amaç için dünya çapında iş birliği yapabildiğini', ['Ağaçların yalnızca bir ülkede yetiştiğini', 'İnternetin gereksiz olduğunu', 'Çevre gününün önemsiz olduğunu']),
      coktan(p('Bir ülkede üretilen ilaç, başka bir ülkede bulunan bilim insanlarının araştırmalarıyla geliştirildi.'), 'Bu durum hangisine örnektir?', 'Bilimde uluslararası iş birliğine', ['Ülkeler arası anlaşmazlığa', 'Turizme', 'Yerel bir geleneğe'])]]),

    'hafta-36': W(36, 7, 'Dünya Vatandaşıyım', 'Yıl sonu değerlendirmesi', () => [[
      kacTane(p('Zeynep yaz tatilinde dedesinin köyüne gidecek; yöresel ürünleri tanıyacak, bir müze gezecek, harçlığıyla bütçe yapacak ve köyün krokisini çizecek.') + p('Öğrenciler Zeynep\'in planını ünitelerle ilişkilendirdi:'), [
        ['Yöresel ürünleri tanımak "Üretim, Dağıtım ve Tüketim" ünitesiyle ilgilidir.', true], ['Müze gezmek "Kültür ve Miras" ünitesiyle ilgilidir.', true], ['Bütçe yapmak "Küresel Bağlantılar" ünitesiyle ilgilidir.', false], ['Kroki çizmek "İnsanlar, Yerler ve Çevreler" ünitesiyle ilgilidir.', true]]),
      tabloSec(p('Öğretmen yıl boyunca öğrenilen becerileri ünitelerle eşleştirdi.'), 'Hangi seçenekte beceriler ünitelerle doğru eşleşmiştir?', ['Etiket okumak', 'Çök-kapan-tutun', 'Oy kullanmak'], ['Üretim, Dağıtım ve Tüketim', 'İnsanlar, Yerler ve Çevreler', 'Etkin Vatandaşlık'], [['Etkin Vatandaşlık', 'İnsanlar, Yerler ve Çevreler', 'Üretim, Dağıtım ve Tüketim'], ['Üretim, Dağıtım ve Tüketim', 'Etkin Vatandaşlık', 'İnsanlar, Yerler ve Çevreler'], ['İnsanlar, Yerler ve Çevreler', 'Üretim, Dağıtım ve Tüketim', 'Etkin Vatandaşlık']], 'an2'),
      kareYol('Kaan, yıl boyunca öğrendiklerini kare oyunuyla tekrar ediyor.', [['Kimlik numaramız bize özeldir.', true], ['Kroki ölçekli çizilmek zorundadır.', false], ['23 Nisan TBMM\'nin açıldığı gündür.', true], ['İhracat, başka ülkeden ürün almaktır.', false], ['Matbaa bilginin yayılmasını kolaylaştırdı.', true]], 'an3')], [
      cocukSec(p('Öğrenciler "dünya vatandaşı olmak" konusunda düşüncelerini paylaşıyor.'), 'Hangi öğrencinin düşüncesi dünya vatandaşlığına uygun değildir?', ['Yalnızca kendi ülkemin sorunları beni ilgilendirir.', 'Farklı kültürlere saygı gösteririm.', 'Doğayı korumak bütün insanların görevidir.', 'Zor durumdaki insanlara yardım ederim.'], 'an4'),
      ortak(p('Okul, yıl sonunda "Değerler Sergisi" düzenledi. 4-A soy ağaçlarını, 4-B afet çantası örneklerini, 4-C bütçe tablolarını, 4-D farklı ülkelerin kültür panolarını sergiledi.'), [
        () => coktan('', 'Hangi sınıfın sergisi "Küresel Bağlantılar" ünitesiyle ilgilidir?', '4-D', ['4-A', '4-B', '4-C']),
        () => coktan('', '4-A\'nın sergisi için hangi kaynaklardan yararlanılmış olabilir?', 'Aile büyükleriyle söyleşi ve eski fotoğraflar', ['Hava durumu raporları', 'Market fişleri', 'Seçim sonuçları'])]),
      coktan(p('Ece yaz tatilinde mahallesinde bir "kitap paylaşım köşesi" kurmak istiyor. Bunun için muhtarlıktan izin aldı, komşularından kitap topladı ve bir afiş hazırladı.'), 'Ece\'nin bu davranışları hangi özelliğini gösterir?', 'Etkin bir vatandaş olarak topluma katkı sağlamasını', ['Bencilliğini', 'Kurallara uymamasını', 'Kitap okumayı sevmemesini'])]]),
  };
  const CSS = `
.b4-kimlik{width:100%;border-radius:3mm;overflow:hidden;border:.4mm solid #9fb3c8;background:linear-gradient(135deg,#e8f1fb,#fdeef0)}.b4-k-ust{background:#c8102e;color:#fff;font-size:3.3mm;text-align:center;padding:.6mm}.b4-k-ic{display:flex;gap:2.5mm;padding:1.8mm}.b4-k-foto{width:17mm;height:21mm;background:#dfe7ef;border-radius:1.5mm;display:grid;place-items:center;font-size:9mm}.b4-kimlik dl{margin:0;display:grid;grid-template-columns:auto 1fr;gap:.2mm 2mm;font-size:3.4mm}.b4-kimlik dt{color:#5b6b7b}.b4-kimlik dd{margin:0}
.b4-serit{display:flex;gap:1mm}.b4-serit>div{flex:1;background:#fff8e6;border-top:1.3mm solid #f4a100;border-radius:1.5mm;padding:1mm .6mm;text-align:center;display:flex;flex-direction:column;gap:.4mm}.b4-serit b{font-weight:400;font-size:3.7mm;color:#b45309}.b4-serit span{font-size:3.2mm;line-height:1.2}
.b4-etiket{display:grid;grid-template-columns:1fr 1fr;gap:.8mm 3mm;border:.6mm dashed #8b5cf6;border-radius:2.5mm;padding:1.5mm 2.5mm;background:#fbf9ff}.b4-etiket div{display:flex;flex-direction:column}.b4-etiket span{font-size:3.3mm;color:#6b5b95}.b4-etiket b{font-weight:400;font-size:3.9mm}
`;
  return { S4, CSS };
};
